local config = {
  ui_story_5072_50720101_1_dialog_content = "Aku sudah mengganti pakaianku. Jadi, apakah ini cukup?",
  ui_story_5072_50720101_2_dialog_content = "Ya, itu dia.",
  ui_story_5072_50720101_3_dialog_content = "Jika seseorang menghentikanmu karena curiga...",
  ui_story_5072_50720101_4_dialog_content = "Cukup berteriak—",
  ui_story_5072_50720101_5_dialog_content = "Beraninya kau mengganggu seorang wanita di siang bolong! Tidak adakah hukum di Twin Pavilions Bay?",
  ui_story_5072_50720101_6_dialog_content = "Sekarang kamu coba.",
  ui_story_5072_50720101_7_dialog_content = "B-Berani-beraninya... kau melecehkan seorang lady...",
  ui_story_5072_50720101_8_dialog_content = "Maaf, saya lupa sisanya.",
  ui_story_5072_50720101_9_dialog_content = "Nah, jika kamu tidak ingat, ada hal lain yang bisa kamu lakukan.",
  ui_story_5072_50720101_10_dialog_content = "Berpretendalah bahwa kamu baru saja sakit karena pertanyaan yang begitu kasar.",
  ui_story_5072_50720101_11_dialog_content = "Lalu jatuh segera, benar? Aku mengerti.",
  ui_story_5072_50720101_12_dialog_content = "Sebagai pengingat, mulai sekarang, kamu bukan lagi tentara bayaran Umbraton yang bersenjata lengkap.",
  ui_story_5072_50720101_13_dialog_content = "Tapi seorang sosialita Longzhou yang halus dan etereal dari sisi lain samudra.",
  ui_story_5072_50720101_14_dialog_content = "Selama kamu tetap mengenakan pakaian ini dan menjaga pedang besar itu tetap terbungkus, tidak seharusnya ada yang curiga.",
  ui_story_5072_50720101_15_dialog_content = "Oke, aku akan berusaha sebaik mungkin untuk mengambil relik-relik itu kembali.",
  ui_story_5072_50720101_16_dialog_content = "Salah, seharusnya \"Aku akan mengambil kembali semua pusaka milikku!\"",
  ui_story_5072_50720101_17_dialog_content = "Benar, akan kuingat!",
  ui_story_5072_50720101_18_dialog_content = "Bagus! Sudah saatnya kita berangkat sekarang.",
  ui_story_5072_50720101_19_dialog_content = "Menuju Twin Pavilions Bay!",
  ui_story_5072_50720101_20_dialog_content = "Ya.",
  ui_story_5072_50720101_21_dialog_content = "Nama saya Arrie, seorang pendekar dari Umbraton.",
  ui_story_5072_50720101_22_dialog_content = "Aku terlahir dengan kutukan dan telah hidup dengan duri di tubuhku untuk menentang kutukan tersebut.",
  ui_story_5072_50720101_23_dialog_content = "Itu memaksa saya menjadi seorang tentara bayaran, meninggalkan keluarga dan kehidupan damai di belakang.",
  ui_story_5072_50720101_24_dialog_content = "Satu-satunya harta yang aku andalkan adalah pedang ajaib.",
  ui_story_5072_50720101_25_dialog_content = "Tidak lama yang lalu, saya bertemu dengan seorang pejabat asing yang menjanjikan saya pekerjaan baru.",
  ui_story_5072_50720101_26_dialog_content = "Yang tidak saya ketahui saat itu adalah petualangan yang menungguku di depan.",
  ui_story_5072_50720101_27_dialog_content = "<color=#e8d9bb>Ketuk, ketuk—</color>",
  ui_story_5072_50720101_28_dialog_content = "Masuklah. Apakah ini Nona Arrie, mungkin?",
  ui_story_5072_50720101_29_dialog_content = "Ya, ini aku. Terima kasih atas keramahan Anda.",
  ui_story_5072_50720101_30_dialog_content = "Maafkan saya, tetapi tentang calon majikan yang Anda sebutkan...",
  ui_story_5072_50720101_31_dialog_content = "Yuk, biar kuperkenalkan.",
  ui_story_5072_50720101_32_dialog_content = "Ini adalah teman yang ingin saya minta Anda bantu, Miss Arrie.",
  ui_story_5072_50720101_33_dialog_content = "Dia adalah Armilla, seorang pengrajin ahli juga dari Longzhou.",
  ui_story_5072_50720101_34_dialog_content = "Dia secara khusus meminta Anda dengan nama untuk tugas ini.",
  ui_story_5072_50720101_35_dialog_content = "Nah, saya rasa \"master\" itu berlebihan. Saya hanya kebetulan melakukannya untuk sementara waktu.",
  ui_story_5072_50720101_36_dialog_content = "Sedangkan wanita ini masih muda namun sudah mendapatkan reputasi yang cukup.",
  ui_story_5072_50720101_37_dialog_content = "Dan sekarang dia telah menarik perhatian Yang Mulia... Masa depan cerah menanti pejuang cantik ini.",
  ui_story_5072_50720101_38_dialog_content = "Itu pujian? Terima kasih.",
  ui_story_5072_50720101_39_dialog_content = "Namun, harus kuakui, banyak cerita tentangku yang dilebih-lebihkan. Aku tidak sehebat itu...",
  ui_story_5072_50720101_40_dialog_content = "Lebih baik bagi Anda untuk memberikan detail pekerjaan dan menilai kemampuan saya sebelum memutuskan.",
  ui_story_5072_50720101_41_dialog_content = "Sepertinya kalian berdua memiliki banyak hal untuk dibicarakan. Saya percaya saya telah menjalankan peran saya sebagai jembatan.",
  ui_story_5072_50720101_42_dialog_content = "Biarkan aku memperbarui syarat-syarat di ruangan bagus ini sehingga kamu bisa bicara sebanyak yang kamu mau.",
  ui_story_5072_50720101_43_dialog_content = "Terima kasih, Yang Mulia.",
  ui_story_5072_50720101_44_dialog_content = "Izinkan saya langsung ke intinya, ya.",
  ui_story_5072_50720101_45_dialog_content = "Saya datang ke Astra untuk mencari barang antik Longzhou yang telah lama hilang.",
  ui_story_5072_50720101_46_dialog_content = "Mereka diselundupkan dari Longzhou ke Twin Pavilions Bay oleh pihak-pihak yang tidak berprinsip dan diperdagangkan antara Bay dan Umbraton.",
  ui_story_5072_50720101_47_dialog_content = "Saya ingin mengetahui detail lengkap setiap barang Longzhou yang beredar di pasar gelap Twin Pavilions Bay.",
  ui_story_5072_50720101_48_dialog_content = "Aku ingin tahu siapa yang menanganinya dan di mana akhirnya barang-barang itu berakhir.",
  ui_story_5072_50720101_49_dialog_content = "Tapi para pedagang yang membeli barang curian tidak pernah menyerah dengan mudah, apalagi di antara barang antik tersebut ada artefak dan relik yang berharga.",
  ui_story_5072_50720101_50_dialog_content = "Jadi, saya membutuhkan tentara bayaran yang tangguh, gigih, dan terampil yang akrab dengan Twin Pavilions Bay dan Umbraton untuk membantu saya.",
  ui_story_5072_50720101_51_dialog_content = "Itu sebabnya kamu mencariku...",
  ui_story_5072_50720101_52_dialog_content = "Itu memang terdengar cocok untukku.",
  ui_story_5072_50720101_53_dialog_content = "Nah, saya ini pandai menilai bakat, meskipun saya sendiri tidak bisa melakukan tugasnya!",
  ui_story_5072_50720101_54_dialog_content = "Jika Anda tidak memiliki pertanyaan lebih lanjut, kita bisa menandatangani garis putus-putus sekarang juga.",
  ui_story_5072_50720101_55_dialog_content = "Aku tidak. Namun, aku punya satu permintaan...",
  ui_story_5072_50720101_56_dialog_content = "Silakan.",
  ui_story_5072_50720101_57_dialog_content = "Jika saya menyelesaikan tugas ini, bisa kah kamu memberikan saya informasi mengenai kutukan?",
  ui_story_5072_50720101_58_dialog_content = "Bahkan yang dari Longzhou pun akan cukup. Saya sangat membutuhkan petunjuk.",
  ui_story_5072_50720101_59_dialog_content = "Tidak masalah. Sebenarnya, aku sudah menanganinya. Aku bisa memberikannya kepadamu sekarang jika perlu.",
  ui_story_5072_50720101_60_dialog_content = "Lagi pula, aku harus mengerjakan pekerjaan rumah tentangmu sebelum mempekerjakanmu, semoga kamu tidak keberatan.",
  ui_story_5072_50720101_61_dialog_content = "Dan saya berharap Anda segera pulih.",
  ui_story_5072_50720101_62_dialog_content = "Terima kasih atas pengertianmu.",
  ui_story_5072_50720101_63_dialog_content = "Saya akan menandatangani kontraknya sekarang.",
  ui_story_5072_50720101_64_dialog_content = "Baiklah, mari kita mulai bisnis.",
  ui_story_5072_50720101_65_dialog_content = "Langkah pertama dari rencana saya adalah menyusup ke berbagai guild dan mengumpulkan informasi rahasia.",
  ui_story_5072_50720101_66_dialog_content = "Tapi kamu terkenal di Umbraton, dan dengan penampilan yang mencolok, kamu tidak bisa masuk begitu saja.",
  ui_story_5072_50720101_67_dialog_content = "Itu benar. Kamu punya saran?",
  ui_story_5072_50720101_68_dialog_content = "Menjadi anonim.",
  ui_story_5072_50720101_69_dialog_content = "Inkognito...?",
  ui_story_5072_50720101_70_dialog_content = "Aku akan memesan pakaian dan aksesori yang sesuai untukmu.",
  ui_story_5072_50720101_71_dialog_content = "Jadi, kamu bisa bergaul dan berurusan dengan berbagai pedagang di Twin Pavilions Bay dengan penyamaran yang sempurna.",
  ui_story_5072_50720101_72_dialog_content = "Apa...?",
  ui_story_5072_50720101_73_dialog_content = "Tapi, duri-duri di tubuhku terlalu tajam untuk kostum biasa.",
  ui_story_5072_50720101_74_dialog_content = "Apakah ini benar-benar akan berhasil...?",
  ui_story_5072_50720101_75_dialog_content = "Ah, sepertinya kamu belum pernah merasakan betapa tangguhnya kualitas sutra yang baik.",
  ui_story_5072_50720101_76_dialog_content = "Dan dengan teknik riasan legendaris dari Longzhou, saya tidak bisa bilang kamu akan berubah menjadi orang yang berbeda...",
  ui_story_5072_50720101_77_dialog_content = "Tapi, seharusnya masih cukup untuk mencapai tujuan kita!",
  ui_story_5072_50720101_78_dialog_content = "Sehebat itu, bukan...?",
  ui_story_5072_50720101_79_dialog_content = "Ayo! Lady Arrie akan segera debut di Twin Pavilions Bay. Saya penasaran seperti apa kepribadian dan penampilannya nanti.",
  ui_story_5072_50720101_80_dialog_content = "Mari kita teliti kemungkinan-kemungkinannya!",
  ui_story_5072_50720101_81_dialog_content = "Umm, tentu?",
  ui_story_5072_50720101_82_dialog_content = "Begitulah cara saya mendapatkan makeover lengkap.",
  ui_story_5072_50720101_83_dialog_content = "Oh, ya. Saya benar-benar di sini di Twin Pavilions Bay dengan identitas baru saya sekarang...",
  ui_story_5072_50720101_84_dialog_content = "(Meski di sekelilingku semua...)",
  ui_story_5072_50720101_85_dialog_content = "Coba lihat dendeng renyah berwarna emas dari Gurun Rediesel! Kamu pasti tidak bisa berhenti mengunyahnya!",
  ui_story_5072_50720101_86_dialog_content = "Buah segar, berair, menyegarkan, lezat, dan baik untuk kulitmu! Bagaimana kalau melihatnya, wanita muda yang terhormat?",
  ui_story_5072_50720101_87_dialog_content = "(Tidak ada yang menyadari kutukan di diriku!)",
  ui_story_5072_50720101_88_dialog_content = "(Tidak ada yang takut padaku... Tidak ada yang mundur atau lari dalam ketakutan...)",
  ui_story_5072_50720101_89_dialog_content = ":(Ini terasa berbeda...)",
  ui_story_5072_50720101_90_dialog_content = "Oh, wanita baik, terhormat, apakah Anda pindah ke Twin Pavilions Bay atau hanya berkunjung?",
  ui_story_5072_50720101_91_dialog_content = "Hanya berkunjung...",
  ui_story_5072_50720101_92_dialog_content = "Maka kamu tidak boleh melewatkan buah segarku. Semuanya diproduksi secara lokal dengan rasa dan kesegaran yang khas!",
  ui_story_5072_50720101_93_dialog_content = "Lalu aku akan... Aku akan memberikan kepercayaanku padamu dan melakukan pembelian.",
  ui_story_5072_50720101_94_dialog_content = "Baiklah, Nyonya! Saya akan mengemasnya untuk Anda sekarang. Makan buah itu baik untuk Anda, terutama saat Anda sedang bepergian.",
  ui_story_5072_50720101_95_dialog_content = "Jika kamu menyukainya, silakan kembali dan dapatkan lebih banyak lagi!",
  ui_story_5072_50720101_96_dialog_content = "S-Tentu...",
  ui_story_5072_50720101_97_dialog_content = "Lihatlah kain premium yang kami tawarkan, Lady?",
  ui_story_5072_50720101_98_dialog_content = "Aku menjual oleh-oleh dari Northland. Mau coba beberapa?",
  ui_story_5072_50720101_99_dialog_content = "Oh tidak, para penjual telah mengelilingiku...",
  ui_story_5072_50720101_100_dialog_content = "Saya tidak di sini untuk menikmati status sebagai sosialita dari Longzhou.",
  ui_story_5072_50720101_101_dialog_content = "Hei, bagaimana menurutmu hidup di Astra sejauh ini, Lady?",
  ui_story_5072_50720101_102_dialog_content = "Tolong berhenti menggodaku, Nona Armilla.",
  ui_story_5072_50720101_103_dialog_content = "Aku tidak menggoda. Aku hanya berusaha membuatmu cepat bersemangat.",
  ui_story_5072_50720101_104_dialog_content = "Maksud saya, mulai dari sekarang, kamu adalah perwakilan dari guild baru yang muncul dari Longzhou—",
  ui_story_5072_50720101_105_dialog_content = "Guild Indigo.",
  ui_story_5072_50720101_106_dialog_content = "Seorang sosialita untuk guild yang, di atas bisnis keluarga, juga sangat tertarik pada barang antik.",
  ui_story_5072_50720101_107_dialog_content = "Dan menjadikannya tujuan hidup untuk memulihkan pusaka yang dijual ke Astra.",
  ui_story_5072_50720101_108_dialog_content = "Sebagai bagian dari saya, saya hanya seorang wanita yang memeriksa Twin Pavilions Bay lebih awal dan membuat segalanya lebih mudah untuk kamu.",
  ui_story_5072_50720101_109_dialog_content = "Mengerti... Aku sudah menghafal semua dialognya.",
  ui_story_5072_50720101_110_dialog_content = "Sekarang, saya harus mulai dengan item pertama di daftar, sebuah toko yang dicurigai melakukan perdagangan pasar gelap.",
  ui_story_5072_50720101_111_dialog_content = "Kalau kamu tidak keberatan, tolong buatkan janji untukku!",
  ui_story_5072_50720101_112_dialog_content = "Ya, Nona.",
  ui_story_5072_50720201_1_dialog_content = "Permisi, bolehkah saya menanyakan apakah pemiliknya ada di sini?",
  ui_story_5072_50720201_2_dialog_content = "Aku datang!",
  ui_story_5072_50720201_3_dialog_content = "Tak bisa kusangka wanita cantik seperti ini mau mengunjungi tokoku!",
  ui_story_5072_50720201_4_dialog_content = "Jangan ragu untuk menjelajah dan bertanya.",
  ui_story_5072_50720201_5_dialog_content = "...",
  ui_story_5072_50720201_6_dialog_content = "Apakah itu dia?",
  ui_story_5072_50720201_7_dialog_content = "Ya, yang pertama di daftar.",
  ui_story_5072_50720201_8_dialog_content = "Berjualan giok dan barang antik hanyalah kedok saat sebenarnya menjadi perantara untuk banyak pembeli di pasar gelap.",
  ui_story_5072_50720201_9_dialog_content = "Sangat mungkin mereka memiliki informasi yang kita inginkan.",
  ui_story_5072_50720201_10_dialog_content = "Ayo berpencar. Kamu tidak masalah melakukan apa yang telah dilatih, bukan?",
  ui_story_5072_50720201_11_dialog_content = "Akan kucoba semampuku.",
  ui_story_5072_50720201_12_dialog_content = "Humph, kamu pikir kamu bisa membodohi saya dengan \"barang antik pemula\" ini?",
  ui_story_5072_50720201_13_dialog_content = "Bahkan stempel resmi ini jelas palsu. Bagaimana berani Anda memalsukan ekspor Longzhou?",
  ui_story_5072_50720201_14_dialog_content = "Wow, jadi kamu seorang ahli... Apakah kamu sedang mencari sesuatu yang khusus?",
  ui_story_5072_50720201_15_dialog_content = "Saya datang ke sini khusus untuk mencari peninggalan asli Longzhou.",
  ui_story_5072_50720201_16_dialog_content = "Banyak barang berharga yang hilang di masa-masa sulit keluargaku...",
  ui_story_5072_50720201_17_dialog_content = "Sekarang sudah menjadi misi saya untuk mendapatkan semuanya kembali untuk guild baru saya dan juga untuk menenangkan leluhur saya.",
  ui_story_5072_50720201_18_dialog_content = "Mengapa Anda tidak menunjukkan kepada saya beberapa barang antik Longzhou yang mungkin Anda peroleh melalui saluran rahasia?",
  ui_story_5072_50720201_19_dialog_content = "Saluran rahasia? Apakah Anda menuduh saya, Lady?",
  ui_story_5072_50720201_20_dialog_content = "Kami adalah toko yang sah. Tidak ada saluran rahasia!",
  ui_story_5072_50720201_21_dialog_content = "Begitu? Tapi, aku rasa kamu telah meremehkan sejauh mana kekayaanku.",
  ui_story_5072_50720201_22_dialog_content = "Selama... Selama itu barang yang tepat, kamu akan mendapatkan lebih banyak dariku daripada orang bodoh mana pun yang bisa kamu jual barang itu.",
  ui_story_5072_50720201_23_dialog_content = "Hmm…",
  ui_story_5072_50720201_24_dialog_content = "Bukan berarti kita tidak bisa...",
  ui_story_5072_50720201_25_dialog_content = "Aku hanya perlu menemukan barangnya terlebih dahulu, dan ada risiko besar yang terlibat. Jadi jika kamu bisa memberikan uang muka...",
  ui_story_5072_50720201_26_dialog_content = "(Deposit? Ya, ini adalah tempat yang tepat!)",
  ui_story_5072_50720201_27_dialog_content = "Apakah kamu tidak percaya padaku?!",
  ui_story_5072_50720201_28_dialog_content = "Mengapa kamu tidak menjelaskan padaku di mana atau apa yang harus kamu lalui untuk mendapatkan jaminan?",
  ui_story_5072_50720201_29_dialog_content = "Tentu, itu... Hei, tunggu sebentar.",
  ui_story_5072_50720201_30_dialog_content = "Jangan bilang kau tidak punya uang dengan cara kau berkelit?",
  ui_story_5072_50720201_31_dialog_content = "Tidak... Apa yang kamu maksud...",
  ui_story_5072_50720201_32_dialog_content = "Aku sudah terlalu banyak bicara padamu, gadis.",
  ui_story_5072_50720201_33_dialog_content = "Itu pintunya. Aku tidak butuh urusanmu!",
  ui_story_5072_50720201_34_dialog_content = "Tapi tapi...",
  ui_story_5072_50720201_35_dialog_content = "Hei, di sana kau, wanitaku! Tolong jangan pergi sendirian lagi karena ini adalah kali pertama kita di Twin Pavilions Bay!",
  ui_story_5072_50720201_36_dialog_content = "Tuan, bukankah Anda sedikit terburu-buru? Lady kami di sini hanya sedikit memaksa, itu saja.",
  ui_story_5072_50720201_37_dialog_content = "Kami mencoba memberikan Anda bisnis, tetapi sikap Anda itu terlalu berlebihan.",
  ui_story_5072_50720201_38_dialog_content = "Kamu pikir kamu sedang berbicara dengan siapa? Kamu harus punya kenalan untuk bekerja di jalan ini, tahu!",
  ui_story_5072_50720201_39_dialog_content = "Aku akan memanggil bantuan jika kau membuat keributan!",
  ui_story_5072_50720201_40_dialog_content = "Keributan? Tidak mungkin, itu hanya akan merusak reputasi guild, jadi tenang saja!",
  ui_story_5072_50720201_41_dialog_content = "Mungkin kita masih bisa berbisnis nanti setelah kamu tenang.",
  ui_story_5072_50720201_42_dialog_content = "Mari, Nona.",
  ui_story_5072_50720201_43_dialog_content = "Hah? Oh, ya.",
  ui_story_5072_50720201_44_dialog_content = "Eh, maaf soal itu...",
  ui_story_5072_50720201_45_dialog_content = "A-Aktingku masih belum cukup baik.",
  ui_story_5072_50720201_46_dialog_content = "Aku kacau...",
  ui_story_5072_50720201_47_dialog_content = "Jangan khawatir, itu memang sudah diperkirakan.",
  ui_story_5072_50720201_48_dialog_content = "Jika ada, kamu justru melakukannya lebih baik daripada yang kuduga.",
  ui_story_5072_50720201_49_dialog_content = "Dan itu juga memberi saya kesempatan untuk masuk ke dalam peran saya!",
  ui_story_5072_50720201_50_dialog_content = "Terima kasih sudah menyelamatkan saya...",
  ui_story_5072_50720201_51_dialog_content = "Tapi satu hal yang pasti, kita harus bermain keras dengan penjaga toko itu.",
  ui_story_5072_50720201_52_dialog_content = "Jadi, mari kita gunakan taktik yang lebih akrab bagi seorang tentara bayaran dalam mengumpulkan info yang kita butuhkan.",
  ui_story_5072_50720201_53_dialog_content = "Apakah pemiliknya masih ada? Saya ingin bicara bisnis!",
  ui_story_5072_50720201_54_dialog_content = "Siapa itu...? Itu kamu, dari sebelumnya di siang hari...",
  ui_story_5072_50720201_55_dialog_content = "Apa yang kamu inginkan? Kau pikir aku akan meringkuk karena kau kembali dan mencari masalah di malam hari?",
  ui_story_5072_50720201_56_dialog_content = "Mencari masalah? Bukankah saya sudah bilang mungkin kita bisa berbisnis nanti?",
  ui_story_5072_50720201_57_dialog_content = "Meskipun kamu tidak bisa memberikan apa yang kami inginkan, mungkin kami punya sesuatu yang kamu cari?",
  ui_story_5072_50720201_58_dialog_content = "Tertarik dengan pernak-pernik baru dari bengkel Longzhou? Dibuat oleh pengrajin ahli, lho.",
  ui_story_5072_50720201_59_dialog_content = "Humph, apa barang bagus yang bisa kamu tawarkan...",
  ui_story_5072_50720201_60_dialog_content = "Nah, coba lihat ini.",
  ui_story_5072_50720201_61_dialog_content = "Itu... Bukankah itu hanya burung mekanik biasa?",
  ui_story_5072_50720201_62_dialog_content = "Burung mekanik biasa? Ayo, saya pikir kamu adalah seorang ahli.",
  ui_story_5072_50720201_63_dialog_content = "Bagaimana kalau kamu melihat lebih dekat dan mencobanya?",
  ui_story_5072_50720201_64_dialog_content = "Apa? Tidak mungkin... Ini... Astaga...!",
  ui_story_5072_50720201_65_dialog_content = "...",
  ui_story_5072_50720201_66_dialog_content = "Pemiliknya pasti terganggu seperti yang telah diprediksi oleh Miss Armilla.",
  ui_story_5072_50720201_67_dialog_content = "Sementara dia sibuk dengan burung mekanik...",
  ui_story_5072_50720201_68_dialog_content = "<color=#e8d9bb>Buk, Buk—</color>",
  ui_story_5072_50720201_69_dialog_content = "Fiuh, aku masuk.",
  ui_story_5072_50720201_70_dialog_content = "Seperti yang kita duga, mereka menyembunyikan rahasia mereka di lantai atas.",
  ui_story_5072_50720201_71_dialog_content = "Koleksi di penyimpanan ini...",
  ui_story_5072_50720201_72_dialog_content = "Barang antik yang sengaja disembunyikan dari pandangan, mungkin ditujukan untuk pasar gelap...",
  ui_story_5072_50720201_73_dialog_content = "Dan pemalsuan... Yah, dia memang bukan pengusaha yang jujur, setelah semua.",
  ui_story_5072_50720201_74_dialog_content = "Tidak ada kesalahan kali ini. Biarkan saya memastikan sebelum melaporkan ke Armilla.",
  ui_story_5072_50720201_75_dialog_content = "Hati-hati, jangan sentuh itu-itu!",
  ui_story_5072_50720201_76_dialog_content = "…?!",
  ui_story_5072_50720201_77_dialog_content = "Siapa itu?!",
  ui_story_5072_50720201_78_dialog_content = "Tunggu, barang-barang antik...",
  ui_story_5072_50720201_79_dialog_content = "<color=#e8d9bb>Klang—Klang—</color>",
  ui_story_5072_50720201_80_dialog_content = "Apa yang sedang terjadi? Mengapa ada kehadiran gelap di sekitar benda-benda ini...?",
  ui_story_5072_50720201_81_dialog_content = "<color=#e8d9bb>Klang—Klang—</color>",
  ui_story_5072_50720201_82_dialog_content = "Dan mereka bergerak... Barang antik itu bergerak.",
  ui_story_5072_50720201_83_dialog_content = "Aku merasakan kebencian... Apakah mereka ingin menyerangku?",
  ui_story_5072_50720201_84_dialog_content = "Tidak, Nona Armilla masih di bawah sana. Saya tidak bisa bertarung habis-habisan di sini.",
  ui_story_5072_50720201_85_dialog_content = "Lebih baik aman daripada menyesal, dan hidup untuk bertarung di hari lain!",
  ui_story_5072_50720202_1_dialog_content = "Lihat, paruh ini tidak hanya bisa digunakan sebagai alat pijat yang hebat, tapi juga bisa membuka cangkang kacang.",
  ui_story_5072_50720202_2_dialog_content = "Betapa indahnya!",
  ui_story_5072_50720202_3_dialog_content = "Aku harus memilikinya! Sebutkan saja harganya, berapapun itu...",
  ui_story_5072_50720202_4_dialog_content = "Sejujurnya, sudah lama aku memimpikan penghancur kacang seperti ini, jadi...",
  ui_story_5072_50720202_5_dialog_content = "Ehem...",
  ui_story_5072_50720202_6_dialog_content = "Ups, aku lupa sama sekali tentang wanitaku! Dia pasti lelah menungguku.",
  ui_story_5072_50720202_7_dialog_content = "Kita akan bicara lebih banyak nanti jika kamu tertarik.",
  ui_story_5072_50720202_8_dialog_content = "Sudah larut dan nona perlu kembali. Aku tidak bisa membuatnya terjaga.",
  ui_story_5072_50720202_9_dialog_content = "Tunggu sebentar, bagaimana dengan clockwork bird...?",
  ui_story_5072_50720202_10_dialog_content = "Kami tidak menjual barang bagus kepada pedagang kotor seperti dia. Ayo, kita pergi!",
  ui_story_5072_50720202_11_dialog_content = "Tentu saja, Nona. Saya hanya mempermainkannya. Dia tidak akan mendapatkannya dengan harga berapa pun!",
  ui_story_5072_50720202_12_dialog_content = "Kamu mempermainkanku?",
  ui_story_5072_50720202_13_dialog_content = "Tidak, ini disebut apa yang berputar, akan kembali lagi!",
  ui_story_5072_50720202_14_dialog_content = "Selamat tinggal.",
  ui_story_5072_50720202_15_dialog_content = "Itu memakan waktu sedikit lebih lama dari yang saya pikirkan.",
  ui_story_5072_50720202_16_dialog_content = "Apa ada kejadian yang tak terduga?",
  ui_story_5072_50720202_17_dialog_content = "Benar.",
  ui_story_5072_50720202_18_dialog_content = "Saya menemukan barang antik dan barang palsu yang disembunyikan di lantai dua.",
  ui_story_5072_50720202_19_dialog_content = "Tapi mereka dikelilingi oleh aura hitam yang aneh... dan mereka bahkan bergerak!",
  ui_story_5072_50720202_20_dialog_content = "Mereka hampir berhasil mengepungku.",
  ui_story_5072_50720202_21_dialog_content = "Sepertinya jebakan itu hanya menunggu untukku.",
  ui_story_5072_50720202_22_dialog_content = "Jebakan? Apakah dia merencanakan ini? Tidak, dia pasti tidak bisa.",
  ui_story_5072_50720202_23_dialog_content = "Jadi, dia bukan masalahnya?",
  ui_story_5072_50720202_24_dialog_content = "Dia tidak tampak mencurigakan atau mencoba menyembunyikan motif apa pun dariku.",
  ui_story_5072_50720202_25_dialog_content = "Jika dia melakukannya dengan sengaja, aku pasti merasakannya.",
  ui_story_5072_50720202_26_dialog_content = "Tapi ini cukup aneh. Benda-benda dengan aura yang menakutkan dan bergerak sendiri...",
  ui_story_5072_50720202_27_dialog_content = "Seolah-olah mereka terpesona atau terkutuk dan diaktifkan oleh kehadiranmu...",
  ui_story_5072_50720202_28_dialog_content = "Dikutuk...?!",
  ui_story_5072_50720202_29_dialog_content = "Tenang saja. Kutukan yang saya bicarakan merujuk pada bagaimana orang-orang Longzhou memohon kepada dewa untuk mendatangkan bencana bagi musuh mereka.",
  ui_story_5072_50720202_30_dialog_content = "Di Longzhou, kami percaya bahwa segala sesuatu adalah makhluk hidup.",
  ui_story_5072_50720202_31_dialog_content = "Apakah itu Fiendlings yang lahir dari alam atau peninggalan kuno, semuanya memiliki anima.",
  ui_story_5072_50720202_32_dialog_content = "Terkadang, mereka disembah dan didoakan, yang sangat berbeda dengan adat istiadat di sini.",
  ui_story_5072_50720202_33_dialog_content = "Aku akan mencatat itu, siapa tahu itu ada hubungannya dengan kutukanmu.",
  ui_story_5072_50720202_34_dialog_content = "Kita akan tahu apa yang terjadi setelah kita berhasil menemukan dalang di balik pagar-pagar ini.",
  ui_story_5072_50720202_35_dialog_content = "Saya mengerti, misi adalah prioritas utama.",
  ui_story_5072_50720202_36_dialog_content = "Lalu…",
  ui_story_5072_50720202_37_dialog_content = "Ada apa?",
  ui_story_5072_50720202_38_dialog_content = "Oh, tidak apa-apa.",
  ui_story_5072_50720202_39_dialog_content = "(Nona Armilla sibuk berbicara dengan pria itu dan tidak bisa memberi tahu saya.)",
  ui_story_5072_50720202_40_dialog_content = "(Jadi, dari mana peringatan itu datang?)",
  ui_story_5072_50720202_41_dialog_content = "(Atau mungkin aku hanya berkhayal mendengar suara...)",
  ui_story_5072_50720301_1_dialog_content = "Maaf, aku masih belum terbiasa merias diriku sendiri.",
  ui_story_5072_50720301_2_dialog_content = "Tak apa. Aksesoris dan penataan rambut memang membutuhkan waktu.",
  ui_story_5072_50720301_3_dialog_content = "Tapi kamu akan memahaminya jika cukup berlatih selama beberapa hari.",
  ui_story_5072_50720301_4_dialog_content = "Aku agak khawatir…",
  ui_story_5072_50720301_5_dialog_content = "Rapatnya tidak berjalan baik. Apakah pemilik toko akan bertemu dengan kita hari ini?",
  ui_story_5072_50720301_6_dialog_content = "Santai saja, begitulah biasanya pembicaraan bisnis. Aku pernah melihat yang lebih buruk.",
  ui_story_5072_50720301_7_dialog_content = "Kami hanya mencoba mencari tahu apakah dia bisa memberikan pencerahan tentang pertemuan Anda tadi malam.",
  ui_story_5072_50720301_8_dialog_content = "Intinya adalah pendukung di belakangnya, jadi jangan tegang begitu!",
  ui_story_5072_50720301_9_dialog_content = "Aku paham.",
  ui_story_5072_50720301_10_dialog_content = "Baiklah, mari kita pergi, Nona.",
  ui_story_5072_50720301_11_dialog_content = "Kita bertemu lagi, Tuan.",
  ui_story_5072_50720301_12_dialog_content = "Nah, kalau bukan si pembuat masalah kecil dari kemarin...",
  ui_story_5072_50720301_13_dialog_content = "B-Beraninya kamu berbicara padaku seperti itu?",
  ui_story_5072_50720301_14_dialog_content = "Aku baru saja melakukannya. Apa yang akan kamu lakukan tentang itu?",
  ui_story_5072_50720301_15_dialog_content = "Semuanya baik-baik saja tadi malam sampai kalian berdua datang dan entah bagaimana gudang saya menjadi berantakan!",
  ui_story_5072_50720301_16_dialog_content = "Para penjaga juga pingsan dan tidak bisa mengingat apa yang terjadi!",
  ui_story_5072_50720301_17_dialog_content = "Sepertinya mereka telah diberi obat oleh... sesuatu dari Longzhou...",
  ui_story_5072_50720301_18_dialog_content = "Hei, jangan bilang kau yang berada di balik semua itu?!",
  ui_story_5072_50720301_19_dialog_content = "Betapa kasarnya kamu mencurigai saya!",
  ui_story_5072_50720301_20_dialog_content = "Saya sedang mempertimbangkan untuk menukarkan sebuah bantuan dari keluarga Lin kepada pejabat di Umbraton untuk sebuah penyelidikan menyeluruh untukmu.",
  ui_story_5072_50720301_21_dialog_content = "Kurasa itu tidak perlu sekarang!",
  ui_story_5072_50720301_22_dialog_content = "T-Tunggu, tolong bantu aku jika kamu punya pengaruh!",
  ui_story_5072_50720301_23_dialog_content = "Saya adalah operator kecil di sini. Saya tidak mampu untuk kehilangan apapun.",
  ui_story_5072_50720301_24_dialog_content = "Yah, barang palsu adalah semua yang kamu miliki, dan saya tidak punya waktu untuk itu!",
  ui_story_5072_50720301_25_dialog_content = "Jika kamu tidak ingin bekerja denganku, ada orang lain yang akan.",
  ui_story_5072_50720301_26_dialog_content = "Aku pergi. Sampai jumpa!",
  ui_story_5072_50720301_27_dialog_content = "Fiuh, sudah berakhir.",
  ui_story_5072_50720301_28_dialog_content = "Apakah performa saya mendapatkan nilai lulus?",
  ui_story_5072_50720301_29_dialog_content = "Lulus? Itu sempurna!",
  ui_story_5072_50720301_30_dialog_content = "Bahkan aku merasa terintimidasi olehnya, Ladyku.",
  ui_story_5072_50720301_31_dialog_content = "Nah, saya merasa percaya diri semakin meningkat seiring saya semakin larut dalam peran tersebut.",
  ui_story_5072_50720301_32_dialog_content = "Sebelum kamu sadari, saya mengatakan hal-hal yang biasanya tidak akan saya katakan.",
  ui_story_5072_50720301_33_dialog_content = "<size=30>Untungnya, saya berada di Twin Pavilions Bay...</size>",
  ui_story_5072_50720301_34_dialog_content = "<size=30>(Jika orang-orang di Umbraton mendengarnya... Aku harus menggali lubang dan menyembunyikan diriku dalam kepompong duri.)</size>",
  ui_story_5072_50720301_35_dialog_content = "Mengapa kita tidak memanfaatkan ini dan melanjutkan upaya kita?",
  ui_story_5072_50720301_36_dialog_content = "Ada banyak toko di daftar saya.",
  ui_story_5072_50720301_37_dialog_content = "Kita akan mengajukan pertanyaan dan mencatat jawabannya.",
  ui_story_5072_50720301_38_dialog_content = "Kemudian kamu bisa menyelinap masuk di malam hari dan memastikan apakah mereka jujur atau tidak.",
  ui_story_5072_50720301_39_dialog_content = "Ya, itu lebih cocok untukku.",
  ui_story_5072_50720301_40_dialog_content = "Ayo sekarang, kau mulai mahir bermain sebagai sosialita.",
  ui_story_5072_50720301_41_dialog_content = "Diperlukan usaha untuk mengobrol dengan penjaga toko.",
  ui_story_5072_50720301_42_dialog_content = "Anda harus berbelanja dan menikmati pemandangan dalam penampilan itu saat Anda memiliki waktu.",
  ui_story_5072_50720301_43_dialog_content = "Apa? Eh, tidak apa-apa.",
  ui_story_5072_50720301_44_dialog_content = "Apa yang saya katakan tentang menjadi tegang? Apakah kamu bahkan makan buah yang kamu beli kemarin?",
  ui_story_5072_50720301_45_dialog_content = "Aku tidak ingin mereka merusaknya jadi aku punya beberapa jeruk.",
  ui_story_5072_50720301_46_dialog_content = "Untuk menebusnya, saya akan mentraktir Anda spesialitas Longzhou setelah kita selesai dengan semua ini.",
  ui_story_5072_50720301_47_dialog_content = "Aduh… yah…",
  ui_story_5072_50720301_48_dialog_content = "Itu perintah dari bosmu.",
  ui_story_5072_50720301_49_dialog_content = "Oke, itu terdengar bagus bagi saya.",
  ui_story_5072_50720401_1_dialog_content = "Baiklah, berhasil masuk malam ini.",
  ui_story_5072_50720401_2_dialog_content = "Nona Armilla pasti sangat teliti dalam penyelidikannya...",
  ui_story_5072_50720401_3_dialog_content = "Dua keranjang pangsit kuah, dua susu kedelai, dan dua batang adonan goreng untuk dibawa pulang.",
  ui_story_5072_50720401_4_dialog_content = "Hei, seorang ahli dalam makanan khas Longzhou, saya lihat.",
  ui_story_5072_50720401_5_dialog_content = "Bukan begitu. Kau didukung oleh Guild Red Shell yang terkenal dan itu membuatmu menjadi franchise yang dikenal.",
  ui_story_5072_50720401_6_dialog_content = "Terima kasih atas pengakuannya. Izinkan saya mengambil pesanan Anda.",
  ui_story_5072_50720401_7_dialog_content = "Sebelum kamu melakukannya, aku penasaran apakah kamu mendengar sesuatu yang menarik di sekitar area barat?",
  ui_story_5072_50720401_8_dialog_content = "Nyonya saya sedikit bosan dan ingin mendengar beberapa cerita!",
  ui_story_5072_50720401_9_dialog_content = "Cerita? Yah, orang-orang kaya di sana memang selalu membicarakannya akhir-akhir ini.",
  ui_story_5072_50720401_10_dialog_content = "Seorang kolektor dengan latar belakang Lumopolis berkeliling membeli barang antik Longzhou.",
  ui_story_5072_50720401_11_dialog_content = "Konon karena relik tersebut berisi roh asing!",
  ui_story_5072_50720401_12_dialog_content = "Pffffft—",
  ui_story_5072_50720401_13_dialog_content = "Apakah dia berpikir dia akan mendapatkan putri asing dengan menyatukan semua serpihan itu?",
  ui_story_5072_50720401_14_dialog_content = "Gila, bukan? Dan dia baru saja menjadi gila beberapa hari yang lalu!",
  ui_story_5072_50720401_15_dialog_content = "Gila, katamu? Bagaimana maksudnya?",
  ui_story_5072_50720401_16_dialog_content = "Dia kebetulan adalah teman bos saya dan tinggal di rumah besar yang mewah.",
  ui_story_5072_50720401_17_dialog_content = "Saya bahkan tidak bisa melihat sekilas tentang dia ketika saya mengantarkan makanan dalam pengiriman.",
  ui_story_5072_50720401_18_dialog_content = "Coba lihat jika kamu tertarik. Aku bisa berikan alamatnya. Semua orang tahu di mana lokasinya.",
  ui_story_5072_50720401_19_dialog_content = "Fantastis, ini tips untuk kamu.",
  ui_story_5072_50720401_20_dialog_content = "Baik! Terima kasih banyak semuanya.",
  ui_story_5072_50720401_21_dialog_content = "Jadi, apa itu Guild Red Shell?",
  ui_story_5072_50720401_22_dialog_content = "Salah satu masalah yang lebih sulit untuk dipecahkan yang pernah kita kunjungi sebelumnya.",
  ui_story_5072_50720401_23_dialog_content = "Pelayan di tempat itu pasti berbicara dengan banyak orang.",
  ui_story_5072_50720401_24_dialog_content = "Saya selalu bisa mendapatkan informasi yang tidak bisa saya dapatkan sendiri dari mereka.",
  ui_story_5072_50720401_25_dialog_content = "Setelah kita selesai makan, ayo kita kunjungi kolektor dari Lumopolis. Mungkin kita akan mendapatkan terobosan.",
  ui_story_5072_50720401_26_dialog_content = "Tentu saja... Pangsit supnya enak...",
  ui_story_5072_50720401_27_dialog_content = "Kamu sudah mulai makan? Kapan mereka menyajikannya?",
  ui_story_5072_50720401_28_dialog_content = "Namun, kunjungan di siang hari itu gagal. Saya tidak bisa melihatnya bahkan dengan identitas palsu saya...",
  ui_story_5072_50720401_29_dialog_content = "Pria itu memang eksentrik.",
  ui_story_5072_50720401_30_dialog_content = "Mansion ini berada dekat jalan yang ramai, namun tetap memancarkan suasana yang menyeramkan dan mengejutkan...",
  ui_story_5072_50720401_31_dialog_content = "Tidak...",
  ui_story_5072_50720401_32_dialog_content = "Aku dengar sesuatu...",
  ui_story_5072_50720401_33_dialog_content = "Jangan mendekat, iblis...",
  ui_story_5072_50720401_34_dialog_content = "Itu dia kolektornya!",
  ui_story_5072_50720401_35_dialog_content = "Dia sama sekali tidak waras... Apa yang dia coba katakan?",
  ui_story_5072_50720401_36_dialog_content = "Roh jahat! Itu roh jahat!",
  ui_story_5072_50720401_37_dialog_content = "Sebuah roh jahat bergentayangan di Twin Pavilions Bay, berkelana...",
  ui_story_5072_50720401_38_dialog_content = "Jika kamu tidak berhati-hati, kamu akan kehilangan akal!",
  ui_story_5072_50720401_39_dialog_content = "Hei!",
  ui_story_5072_50720401_40_dialog_content = "Ada apa?!",
  ui_story_5072_50720401_41_dialog_content = "...",
  ui_story_5072_50720401_42_dialog_content = "Semua penjaga telah tersingkir!",
  ui_story_5072_50720401_43_dialog_content = "...",
  ui_story_5072_50720401_44_dialog_content = "Dan collector juga...",
  ui_story_5072_50720401_45_dialog_content = "Kamu...",
  ui_story_5072_50720401_46_dialog_content = "Siapa kamu?!",
  ui_story_5072_50720401_47_dialog_content = "Kamu memegang senjata! Kamu pembunuhnya?!",
  ui_story_5072_50720401_48_dialog_content = "...",
  ui_story_5072_50720401_49_dialog_content = "Aura gelap ini sama seperti yang ada pada barang antik terkutuk!",
  ui_story_5072_50720401_50_dialog_content = "Apakah ini roh jahat yang diceritakan oleh kolektor itu?",
  ui_story_5072_50720401_51_dialog_content = "!!!",
  ui_story_5072_50720401_52_dialog_content = "Cepat sekali!",
  ui_story_5072_50720401_53_dialog_content = "Ada begitu banyak bayangan di ruangan ini...",
  ui_story_5072_50720401_54_dialog_content = "Tidak, bukan hanya bayangan biasa... Mereka terasa bermusuhan, sangat mirip seperti...",
  ui_story_5072_50720401_55_dialog_content = "Energi pedang?!",
  ui_story_5072_50720401_56_dialog_content = "<color=#e8d9bb>Klang—Ka-thunk—</color>",
  ui_story_5072_50720401_57_dialog_content = "Apakah dia mencoba menghancurkan segalanya di sini?! Mustahil!",
  ui_story_5072_50720401_58_dialog_content = "Ha-",
  ui_story_5072_50720401_59_dialog_content = "Aku akan melawanmu!",
  ui_story_5072_50720402_1_dialog_content = "<color=#e8d9bb>Aduh—!</color>",
  ui_story_5072_50720402_2_dialog_content = "...",
  ui_story_5072_50720402_3_dialog_content = "*Wusss...*",
  ui_story_5072_50720402_4_dialog_content = "Aku tidak mengerti... Aku seharusnya bisa mengalahkannya dengan pedang sihirku.",
  ui_story_5072_50720402_5_dialog_content = "Tapi bayangan-bayangan ini terus muncul dan membentuk kembali setelah setiap potongan seolah-olah saya sama sekali tidak memukul mereka...",
  ui_story_5072_50720402_6_dialog_content = "Dan mereka semakin mendekat...",
  ui_story_5072_50720402_7_dialog_content = "Harus bisa menjaga mereka tetap di bayangan dengan cara apapun.",
  ui_story_5072_50720402_8_dialog_content = "<color=#e8d9bb>Gedebuk-</color>",
  ui_story_5072_50720402_9_dialog_content = "Aduh...",
  ui_story_5072_50720402_10_dialog_content = "Ruang ini penuh dengan barang-barang. Tidak ada lagi ruang untuk berlari.",
  ui_story_5072_50720402_11_dialog_content = "Oh, tidak...",
  ui_story_5072_50720402_12_dialog_content = "Roaar—",
  ui_story_5072_50720402_13_dialog_content = "Energi pedangnya mencekikku!",
  ui_story_5072_50720402_14_dialog_content = "Sakit rasanya dengan semua emosi dan pikiran negatif...",
  ui_story_5072_50720402_15_dialog_content = "Tenangkan dirimu.",
  ui_story_5072_50720402_16_dialog_content = "Apakah itu suara yang sama yang memperingatkanku sebelumnya?",
  ui_story_5072_50720402_17_dialog_content = "Jadi aku bukan salah dengar, tapi sebenarnya...",
  ui_story_5072_50720402_18_dialog_content = "Pedangku?!",
  ui_story_5072_50720402_19_dialog_content = "Tetap fokus. Jarak pandang di sini terlalu buruk untuk kamu melihat kebenaran yang terselubung oleh bayangan.",
  ui_story_5072_50720402_20_dialog_content = "Jangan khawatir tentang aura hitam itu. Itu hanya ada untuk mengalihkan perhatianmu!",
  ui_story_5072_50720402_21_dialog_content = "Target Anda berada di ujung paling akhir.",
  ui_story_5072_50720402_22_dialog_content = "Lompat dan serang. Aku akan merencanakan jalannya untukmu.",
  ui_story_5072_50720402_23_dialog_content = "Aku tidak punya waktu untuk merenungkan semua yang kamu katakan, tapi...",
  ui_story_5072_50720402_24_dialog_content = "Aku mengerti dan aku akan mempercayaimu!",
  ui_story_5072_50720402_25_dialog_content = "!!!",
  ui_story_5072_50720402_26_dialog_content = "Aku berhasil! Dan itu juga solid.",
  ui_story_5072_50720402_27_dialog_content = "...",
  ui_story_5072_50720402_28_dialog_content = "Bayangan telah menghilang. Sekarang, biarkan aku melihat siapa dirimu yang sebenarnya.",
  ui_story_5072_50720402_29_dialog_content = "...",
  ui_story_5072_50720402_30_dialog_content = "Apa? Bukankah itu server yang menceritakan cerita kepada kita?",
  ui_story_5072_50720402_31_dialog_content = "Dia hanya pria biasa, jadi bagaimana dia bisa begitu tangguh...?",
  ui_story_5072_50720402_32_dialog_content = "Mungkin itu pedangnya... Kemungkinan besar memiliki kekuatan khusus seperti milikku.",
  ui_story_5072_50720402_33_dialog_content = "...",
  ui_story_5072_50720402_34_dialog_content = "Membeku.",
  ui_story_5072_50720402_35_dialog_content = "Di sini!",
  ui_story_5072_50720402_36_dialog_content = "Seseorang masuk...?",
  ui_story_5072_50720402_37_dialog_content = "Barusan aku melihat sosok aneh dengan pedang raksasa masuk!",
  ui_story_5072_50720402_38_dialog_content = "Tapi di situlah kolektor gila itu tinggal. Kita harus membiarkannya sendiri.",
  ui_story_5072_50720402_39_dialog_content = "Tidak, jika kita bisa menyelesaikan kasus ini, kita mungkin akan mendapatkan hadiah baik dari Tuan Kota maupun guild!",
  ui_story_5072_50720402_40_dialog_content = "Ini tidak baik. Seseorang sedang masuk sekarang...",
  ui_story_5072_50720402_41_dialog_content = "Akan buruk jika mereka melihatku.",
  ui_story_5072_50720402_42_dialog_content = "Aku harus kembali dan melapor kepada Miss Armilla.",
  ui_story_5072_50720501_1_dialog_content = "Tuan, saya harap Anda dapat memberikan penjelasan yang tepat untuk Red Shell Guild.",
  ui_story_5072_50720501_2_dialog_content = "Dalam bisnis, integritas adalah yang utama, tanpa terkecuali.",
  ui_story_5072_50720501_3_dialog_content = "Tapi, apakah itu yang terjadi tadi malam atau pertanyaan sebelumnya tentang barang antik...",
  ui_story_5072_50720501_4_dialog_content = "Kau tidak mengucapkan sedikit pun kebenaran, jadi apa maksudmu?",
  ui_story_5072_50720501_5_dialog_content = "Red Shell Guild berbohong?",
  ui_story_5072_50720501_6_dialog_content = "Mereka pasti melakukannya. Mereka mengklaim bahwa kolektor gila itu tidak ada hubungannya dengan mereka, padahal itu semua tentang mereka!",
  ui_story_5072_50720501_7_dialog_content = "Semua barang di rumah korban dibeli dari mereka. Saya dengar mereka juga mengirim pembunuhnya.",
  ui_story_5072_50720501_8_dialog_content = "Tidak, itu sama sekali tidak benar!",
  ui_story_5072_50720501_9_dialog_content = "Kasus semalam itu tiba-tiba dan tak terduga. Kami hanya butuh waktu untuk menyelidikinya!",
  ui_story_5072_50720501_10_dialog_content = "Baiklah, mengenai keterlibatan Red Shell dalam serangan itu...",
  ui_story_5072_50720501_11_dialog_content = "Guild Ziyun akan menunggu penyelidikan Anda.",
  ui_story_5072_50720501_12_dialog_content = "Tapi kami ingin kamu menjelaskan tentang perintah pasar gelap.",
  ui_story_5072_50720501_13_dialog_content = "Ketika saya mengunjungi beberapa hari yang lalu, kamu jelas tidak pernah terlibat dalam transaksi semacam itu.",
  ui_story_5072_50720501_14_dialog_content = "Tapi sekarang ini sudah terungkap, apa pendapatmu tentang itu?",
  ui_story_5072_50720501_15_dialog_content = "Wow, keluar dari mulut buaya, masuk mulut harimau!",
  ui_story_5072_50720501_16_dialog_content = "Aku tahu Red Shell memiliki hubungan dengan pasar gelap!",
  ui_story_5072_50720501_17_dialog_content = "Tolong turun, semuanya, dan tenang saja. Semuanya akan terselesaikan tepat waktu.",
  ui_story_5072_50720501_18_dialog_content = "Kami memang menangani barang antik Longzhou dari asal yang tidak diketahui.",
  ui_story_5072_50720501_19_dialog_content = "Tapi kita semua tahu bahwa untuk sukses di Umbraton dan Twin Pavilions Bay, kamu harus berjabat tangan dengan kedua pihak.",
  ui_story_5072_50720501_20_dialog_content = "Bukan saya menolak untuk membocorkan, tapi hubungan bawah tanah bukanlah sesuatu yang ingin kamu umumkan...",
  ui_story_5072_50720501_21_dialog_content = "Saya melakukannya karena kekhawatiran akan kedamaian di Twin Pavilions Bay.",
  ui_story_5072_50720501_22_dialog_content = "Untuk kedamaian di Teluk? Lebih seperti karena kekhawatiran Anda sendiri terhadap bisnis Anda menurut saya.",
  ui_story_5072_50720501_23_dialog_content = "Tapi semua itu tidak penting dengan tempat kita berada sekarang.",
  ui_story_5072_50720501_24_dialog_content = "Termasuk wanita saya di sini, banyak orang melihat tadi malam bahwa pembunuh itu bekerja untuk Anda.",
  ui_story_5072_50720501_25_dialog_content = "Jika kasus pembunuhan perampokan ini terbongkar, tidak akan ada tempat untuk guildmu di kota ini.",
  ui_story_5072_50720501_26_dialog_content = "Hei, jangan tergesa-gesa sekarang!",
  ui_story_5072_50720501_27_dialog_content = "Bisnis pasar gelap tetaplah bisnis.",
  ui_story_5072_50720501_28_dialog_content = "Tapi hanya bandit yang akan merampok dan menjarah seperti itu.",
  ui_story_5072_50720501_29_dialog_content = "Tidak mungkin saya merusak masa depan guild saya demi keuntungan kecil seperti itu!",
  ui_story_5072_50720501_30_dialog_content = "Apakah kamu berkata jujur?",
  ui_story_5072_50720501_31_dialog_content = "Aku bersumpah demi hidupku sendiri!",
  ui_story_5072_50720501_32_dialog_content = "Saya tidak berpikir kamu akan mengambil risiko itu juga. Sebenarnya, saya curiga pria itu diam-diam bekerja untuk orang lain.",
  ui_story_5072_50720501_33_dialog_content = "Jadi selama ini kamu telah memeras informasi dariku?!",
  ui_story_5072_50720501_34_dialog_content = "Jangan berkelit. Kita akan kembali ke bagaimana kamu berbohong padaku.",
  ui_story_5072_50720501_35_dialog_content = "Namun, mencari tahu siapa yang membayar orang itu akan menguntungkan bagi kita berdua.",
  ui_story_5072_50720501_36_dialog_content = "Dia hanya karyawan biasa. Saya tidak mengerti mengapa ada yang ingin membeli kesetiaannya.",
  ui_story_5072_50720501_37_dialog_content = "Maka hanya ada satu kemungkinan yang tersisa.",
  ui_story_5072_50720501_38_dialog_content = "Tempat apa itu?",
  ui_story_5072_50720501_39_dialog_content = "Beberapa relik yang beredar di pasar gelap adalah artefak kuat yang bisa mengendalikan pikiran siapa pun yang memegangnya.",
  ui_story_5072_50720501_40_dialog_content = "Lagipula, orang itu bertarung seperti juara dunia dengan pedangnya... Oh, dan satu hal lagi.",
  ui_story_5072_50720501_41_dialog_content = "Saya dengar Tuan Muda dari guild Anda juga menyaksikan pembunuh bayaran tadi malam?",
  ui_story_5072_50720501_42_dialog_content = "Apa peluangnya dia kebetulan berada di dekat tempat ketika salah satu pekerjanya sedang melakukan kejahatan?",
  ui_story_5072_50720501_43_dialog_content = "Sulit untuk tidak mencium sesuatu yang mencurigakan di situ.",
  ui_story_5072_50720501_44_dialog_content = "Hei, berhenti menuduh orang tanpa bukti!",
  ui_story_5072_50720501_45_dialog_content = "Dia pergi ke bar bersama beberapa teman dan hanya secara tidak sengaja menemukannya dalam perjalanan pulang.",
  ui_story_5072_50720501_46_dialog_content = "Jika kita melangkah lebih jauh, bukankah itu juga akan membuat lady Anda menjadi tersangka?",
  ui_story_5072_50720501_47_dialog_content = "Oh, itu teori baru. Mengapa Anda tidak menjelaskannya bagaimana caranya?",
  ui_story_5072_50720501_48_dialog_content = "Sangat biasa bagi tuan muda kita yang cukup ekstrovert untuk pergi minum di malam hari.",
  ui_story_5072_50720501_49_dialog_content = "Tapi, apa yang dilakukan oleh nona Anda berkeliling daripada tinggal di rumah?",
  ui_story_5072_50720501_50_dialog_content = "Dalam arti itu, kehadiran dan kesaksiannya justru membuatnya menjadi tersangka utama!",
  ui_story_5072_50720501_51_dialog_content = "Jangan bilang ini semua adalah rekayasa dari guildmu untuk merusak nama kami?",
  ui_story_5072_50720501_52_dialog_content = "Apakah kamu tahu sesuatu tentang wanita dari Ziyun Guild?",
  ui_story_5072_50720501_53_dialog_content = "Tidak. Tapi mengingat apa yang baru saja dikatakan, mungkin ada sesuatu yang aneh tentang dirinya.",
  ui_story_5072_50720501_54_dialog_content = "Aku baru saja pergi sebentar dan sudah dituduh.",
  ui_story_5072_50720501_55_dialog_content = "Apakah kamu menuduhku sebagai tersangka?",
  ui_story_5072_50720501_56_dialog_content = "Wow, kehadirannya... Hanya bisa milik seorang wanita berkelas!",
  ui_story_5072_50720501_57_dialog_content = "Itu asumsi yang masuk akal!",
  ui_story_5072_50720501_58_dialog_content = "Mengapa kamu tidak membuat polling dan melihat apakah itu adil atau tidak.",
  ui_story_5072_50720501_59_dialog_content = "Tentu saja. Siapa saja, silakan maju jika kalian juga mencurigai saya.",
  ui_story_5072_50720501_60_dialog_content = "...",
  ui_story_5072_50720501_61_dialog_content = "Karena tidak ada komentar lagi, saya akan menceritakan kembali pertemuan saya semalam.",
  ui_story_5072_50720501_62_dialog_content = "Tidak seperti tuan muda yang merunduk dan bersembunyi, tidak mau memberi kesaksian.",
  ui_story_5072_50720501_63_dialog_content = "Kenapa kau... Baiklah, kenapa kau tidak menjelaskan dirimu sendiri?",
  ui_story_5072_50720501_64_dialog_content = "Pertama, saya datang ke Twin Pavilions Bay untuk mencari pusaka keluarga yang hilang, jadi tidak cukup hanya melalui jalur normal.",
  ui_story_5072_50720501_65_dialog_content = "Namun, malam hari di Teluk menawarkan kerumunan yang lebih beragam dari yang saya bayangkan...",
  ui_story_5072_50720501_66_dialog_content = "Akhirnya kami berhasil melacak kolektor dengan usaha yang besar hanya untuk ditolak masuk, memaksa kami untuk mengintai kediamannya.",
  ui_story_5072_50720501_67_dialog_content = "Dan kami akhirnya mengalami beberapa masalah dengan Vilanor's Host, ditambah dengan tuduhan yang tidak berdasar dari orang-orang yang mencurigakan seperti kamu.",
  ui_story_5072_50720501_68_dialog_content = "Tidak adakah hukum di Twin Pavilions Bay?!",
  ui_story_5072_50720501_69_dialog_content = "...",
  ui_story_5072_50720501_70_dialog_content = "Mengenai kemunculan mengerikan dari Tuan Rumah Vilanor...",
  ui_story_5072_50720501_71_dialog_content = "Ambillah peringatan saya dengan serius dan jangan salahkan saya karena tidak memperingatkan Anda sebelumnya.",
  ui_story_5072_50720502_1_dialog_content = "Dan itulah sejauh pertemuan saya dengannya.",
  ui_story_5072_50720502_2_dialog_content = "Jangan ragu untuk mengajukan pertanyaan apa pun yang Anda miliki sekarang.",
  ui_story_5072_50720502_3_dialog_content = "Tapi aku tidak ingin mendengar keraguan lagi setelah hari ini, atau lainnya.",
  ui_story_5072_50720502_4_dialog_content = "...",
  ui_story_5072_50720502_5_dialog_content = "Jadi, ada masalah lain yang ingin Anda diskusikan?",
  ui_story_5072_50720502_6_dialog_content = "Nah, kamu jelas dan dapat dipercaya. Saya tidak bisa menemukan kelemahan dalam ceritamu sekarang.",
  ui_story_5072_50720502_7_dialog_content = "Sepertinya semua guild harus belajar dari ini dan berhati-hati terhadap Vilanor's Host.",
  ui_story_5072_50720502_8_dialog_content = "Namun…",
  ui_story_5072_50720502_9_dialog_content = "Utarakan pikiranmu.",
  ui_story_5072_50720502_10_dialog_content = "Saya lihat kamu selalu membawa tas instrumen musik yang jelas besar dan merepotkan.",
  ui_story_5072_50720502_11_dialog_content = "May Saya bertanya, kenapa kamu selalu membawanya bersamamu?",
  ui_story_5072_50720502_12_dialog_content = "!",
  ui_story_5072_50720502_13_dialog_content = "...",
  ui_story_5072_50720502_14_dialog_content = "Mengapa kamu berbelit-belit?",
  ui_story_5072_50720502_15_dialog_content = "Ketika kamu masih meragukan diriku!",
  ui_story_5072_50720502_16_dialog_content = "Saya berasal dari Longzhou, dan barang-barang mewah seperti ini adalah kebutuhan bagi sosialita Longzhou yang suka bepergian.",
  ui_story_5072_50720502_17_dialog_content = "Selain urusan keluarga, saya juga berharap bisa bertemu dan berbagi ide dengan pecinta musik lokal.",
  ui_story_5072_50720502_18_dialog_content = "Siapa yang tahu sekalipun Twin Pavilions Bay tampak menerima, tidak ada tempat untuk instrumen musikku!",
  ui_story_5072_50720502_19_dialog_content = "Jika kamu ingin memeriksa, akan kuserahkan padamu!",
  ui_story_5072_50720502_20_dialog_content = "Maaf telah meragukanmu.",
  ui_story_5072_50720502_21_dialog_content = "Bagaimana saya bisa terus mencurigai ketika Anda telah menjelaskan diri dengan sangat jelas?",
  ui_story_5072_50720502_22_dialog_content = "Mohon maafkan tindakan saya. May semoga Anda segera mencapai tujuan Anda.",
  ui_story_5072_50720502_23_dialog_content = "Fiuh... Senang itu sudah berakhir.",
  ui_story_5072_50720502_24_dialog_content = "Kesempurnaan, kesempurnaan mutlak. Kerja bagus, Arrie.",
  ui_story_5072_50720502_25_dialog_content = "Jantungku berdetak kencang ketika kamu menawarkan agar dia memeriksa kasusnya.",
  ui_story_5072_50720502_26_dialog_content = "Kamu membuat panggilan yang berani.",
  ui_story_5072_50720502_27_dialog_content = "Nah, itu bukan yang sedang kupikirkan.",
  ui_story_5072_50720502_28_dialog_content = "Aku berharap dia menyerah begitu dia tahu dia tidak bisa menggerakkan kasus ini.",
  ui_story_5072_50720502_29_dialog_content = "Itu juga benar.",
  ui_story_5072_50720502_30_dialog_content = "Namun, dengan informasi yang baru saja kita dapat, saya punya firasat tentang apa yang harus dilakukan selanjutnya.",
  ui_story_5072_50720502_31_dialog_content = "Kita akan berpisah. Kamu terus mencari petunjuk di sekitar distrik bisnis.",
  ui_story_5072_50720502_32_dialog_content = "Untukku, aku akan mengunjungi beberapa teman lama dan mencoba menggali cerita tentang Vilanor's Host.",
  ui_story_5072_50720502_33_dialog_content = "Lalu kita akan mencari tahu sisanya setelah kita bertemu kembali.",
  ui_story_5072_50720502_34_dialog_content = "Tentu. Aku akan melakukan yang terbaik.",
  ui_story_5072_50720503_1_dialog_content = "Hei, peramal, ramalanmu sangat meleset.",
  ui_story_5072_50720503_2_dialog_content = "Kamu memberitahuku beberapa hari lalu bahwa masalah akan datang, tapi pada akhirnya aku malah menghasilkan uang.",
  ui_story_5072_50720503_3_dialog_content = "Bukankah kamu menjamin kalau ini benar atau uangku kembali? Aku mau pengembalian dana!",
  ui_story_5072_50720503_4_dialog_content = "Ayo, Tuan, jangan tergesa-gesa begitu.",
  ui_story_5072_50720503_5_dialog_content = "Jika saya tidak salah ingat, pembacaanmu tidak terlalu menguntungkan. Harimau Yang dan Babi Yin, benar?",
  ui_story_5072_50720503_6_dialog_content = "Kamu masih ingat itu?",
  ui_story_5072_50720503_7_dialog_content = "Tentu saja. Ini menunjukkan pertanda buruk.",
  ui_story_5072_50720503_8_dialog_content = "Keuntungan kecil yang kamu dapatkan... Apakah itu berasal dari investasi?",
  ui_story_5072_50720503_9_dialog_content = "Pengembalian yang sedikit hanyalah simbol tukar ganti atas kekayaan besar Anda. Lanjutkan dengan hati-hati, agar Anda tidak menemukan diri Anda kehilangan segalanya.",
  ui_story_5072_50720503_10_dialog_content = "Kalah, kalah!",
  ui_story_5072_50720503_11_dialog_content = "Semuanya, semuanya!",
  ui_story_5072_50720503_12_dialog_content = "Dua gagak milikmu itu adalah pertanda buruk, sama seperti dirimu!",
  ui_story_5072_50720503_13_dialog_content = "Meski saya juga mengakui mereka bisa mengganggu, mereka sebenarnya jalak, bukan gagak.",
  ui_story_5072_50720503_14_dialog_content = "Baiklah, peramal, mungkin ramalanmu meleset, tapi kamu cukup baik dalam bercerita.",
  ui_story_5072_50720503_15_dialog_content = "Cerita yang kamu ceritakan tentang gadis pelayan yang menjadi ratu bawah laut itu bagus. Bagaimana dengan cerita lainnya?",
  ui_story_5072_50720503_16_dialog_content = "Baiklah, aku punya satu lagi. Ini tentang seorang pendekar pedang yang terkutuk.",
  ui_story_5072_50720503_17_dialog_content = "Semuanya, berkumpul dan tolong berikan aku sekeping dua koin jika kalian bisa.",
  ui_story_5072_50720503_18_dialog_content = "Dahulu kala, ada seorang pendekar pedang yang terkutuk...",
  ui_story_5072_50720503_19_dialog_content = "Siapa yang menderita anemia, menderita pertumbuhan duri, namun menghunus pedang besar!",
  ui_story_5072_50720503_20_dialog_content = "Bilah pedang ini bisa mengalahkan setiap iblis dan menghancurkan setiap musuh.",
  ui_story_5072_50720503_21_dialog_content = "Pendekar pedang itu berkelana sepanjang Sungai Emas, tidak mencari kekayaan maupun ketenaran...",
  ui_story_5072_50720503_22_dialog_content = "Tapi dalam pencarian yang fokus untuk memecahkan segala macam kutukan aneh.",
  ui_story_5072_50720503_23_dialog_content = "Karena dia percaya hanya dengan memecahkan semua kutukan di dunia, dia bisa menemukan cara untuk menyelamatkan dirinya sendiri.",
  ui_story_5072_50720503_24_dialog_content = "Dan sekarang, pendekar pedang itu telah datang ke Twin Pavilions Bay di muara Sungai Emas.",
  ui_story_5072_50720503_25_dialog_content = "Akankah dia mengalahkan kutukan dan membebaskan dirinya sendiri?",
  ui_story_5072_50720503_26_dialog_content = "Sampai jumpa lagi!",
  ui_story_5072_50720503_27_dialog_content = "Hei kamu, jangan berhenti di tengah jalan!",
  ui_story_5072_50720503_28_dialog_content = "Ya!",
  ui_story_5072_50720503_29_dialog_content = "Nah, jika kamu menginginkan lebih, saya percaya saya akan membutuhkan sedikit motivasi moneter.",
  ui_story_5072_50720503_30_dialog_content = "Moneter, moneter!",
  ui_story_5072_50720503_31_dialog_content = "Motivasi, motivasi!",
  ui_story_5072_50720503_32_dialog_content = "Kamu mau uang untuk itu? Aku pergi dari sini.",
  ui_story_5072_50720503_33_dialog_content = "Pedang terkutuk?",
  ui_story_5072_50720503_34_dialog_content = "Bukankah itu yang telah terjadi akhir-akhir ini di kota ini?",
  ui_story_5072_50720503_35_dialog_content = "Apakah kamu mencoba menjual cerita itu sebagai milikmu sendiri? Tidak mungkin!",
  ui_story_5072_50720503_36_dialog_content = "Tidak, itu bukan maksudnya. Bukankah kalian semua memintaku untuk menceritakan sebuah kisah?",
  ui_story_5072_50720503_37_dialog_content = "Aku pikir Tuan Rumah Vilanor sudah cukup mengerikan untuk menakuti semua orang.",
  ui_story_5072_50720503_38_dialog_content = "Bagaimana bisa kau membuatnya terdengar seperti cerita heroik? Ada batas kreativitas yang diperbolehkan, tahu.",
  ui_story_5072_50720503_39_dialog_content = "Huh, garis yang tipis antara baik dan jahat.",
  ui_story_5072_50720503_40_dialog_content = "Pendekar pedang mungkin tampak jahat di matamu hari ini, tapi bisa jadi berubah menjadi pahlawan besok.",
  ui_story_5072_50720503_41_dialog_content = "Minggir... Kamu! Siapa yang memberimu izin untuk membuka toko di sini?",
  ui_story_5072_50720503_42_dialog_content = "Ayo, saya hanya mencoba mencari nafkah di sini. Kenapa kamu tidak bisa meninggalkan saya sendiri?",
  ui_story_5072_50720503_43_dialog_content = "Pertama-tama, melanggar hukum bagi Anda untuk mendirikan lapak di sini.",
  ui_story_5072_50720503_44_dialog_content = "Kedua, kami sedang memasang poster buronan di sini dan itu menjadi prioritas.",
  ui_story_5072_50720503_45_dialog_content = "Pergilah jika kamu tahu apa yang terbaik untukmu!",
  ui_story_5072_50720503_46_dialog_content = "Baiklah. Tapi biarkan aku memberimu penjelasan tentang hadiah ini sebelum aku pergi.",
  ui_story_5072_50720503_47_dialog_content = "Hmm, Yin Anjing dan Yin Kambing. Saya khawatir orang di poster bukanlah orang yang seharusnya Anda cari.",
  ui_story_5072_50720503_48_dialog_content = "Itu bukan urusanmu!",
  ui_story_5072_50720503_49_dialog_content = "Baik, baik, aku mengerti tidak ada perbuatan baik yang tak dihukum. Selamat tinggal, lalu.",
  ui_story_5072_50720601_1_dialog_content = "Jalanan di sisi timur tampak lebih ramai dari biasanya hari ini.",
  ui_story_5072_50720601_2_dialog_content = "Apa ini...?",
  ui_story_5072_50720601_3_dialog_content = "Sebuah poster buronan untuk Tuan Rumah Vilanor?!",
  ui_story_5072_50720601_4_dialog_content = "Tidak heran orang-orang berbicara tentang seseorang dengan pedang besar yang aneh...",
  ui_story_5072_50720601_5_dialog_content = "Aku harus lebih berhati-hati dan memastikan pedang ajaibku tidak terlihat...",
  ui_story_5072_50720601_6_dialog_content = "Beruntung aku punya kasus ini. Selama aku bertindak alami, tidak ada yang harus curiga...",
  ui_story_5072_50720601_7_dialog_content = "Awas, Arrie, ada seseorang yang mendekat dengan cepat!",
  ui_story_5072_50720601_8_dialog_content = "Apa?!",
  ui_story_5072_50720601_9_dialog_content = "Berani-beraninya kamu melecehkan seorang wanita di siang bolong!",
  ui_story_5072_50720601_10_dialog_content = "Tidak adakah hukum di Twin Pavilions Bay?",
  ui_story_5072_50720601_11_dialog_content = "Ampuni aku, Nona Muda, ampuni aku!",
  ui_story_5072_50720601_12_dialog_content = "Hah?",
  ui_story_5072_50720601_13_dialog_content = "A-Aku sama sekali tidak bermaksud jahat!",
  ui_story_5072_50720601_14_dialog_content = "Saya mendengar anggota guild berbicara tentang betapa mahirnya sang Nyonya Ziyun sebagai musisi...",
  ui_story_5072_50720601_15_dialog_content = "Saya berasumsi Anda pasti seorang wanita yang elegan, jadi saya pikir saya akan menawarkan layanan bengkel saya kepada Anda.",
  ui_story_5072_50720601_16_dialog_content = "Aku akan mundur sekarang jika aku telah menyinggungmu!",
  ui_story_5072_50720601_17_dialog_content = "(Dia tampak cukup biasa untuk menjadi seorang pedagang.)",
  ui_story_5072_50720601_18_dialog_content = "(Tapi pedangku belum pernah salah, jadi seharusnya aku bertanya.)",
  ui_story_5072_50720601_19_dialog_content = "Apakah dia benar-benar hanya seorang pedagang?",
  ui_story_5072_50720601_20_dialog_content = "Hmm…",
  ui_story_5072_50720601_21_dialog_content = "Mungkin dia juga seorang pencuri.",
  ui_story_5072_50720601_22_dialog_content = "Pokoknya, aku merasakan sedikit kebencian tapi tidak ada ancaman besar. Kamu bisa santai.",
  ui_story_5072_50720601_23_dialog_content = "Fiuh…",
  ui_story_5072_50720601_24_dialog_content = "Mereka sedang mencari Tuan Rumah Vilanor akhir-akhir ini, jadi kita harus berhati-hati.",
  ui_story_5072_50720601_25_dialog_content = "Kamu telah berada di sisiku sepanjang waktu, pedang ajaib, jadi coba jangan menakutiku.",
  ui_story_5072_50720601_26_dialog_content = "Benar sekali, Arrie.",
  ui_story_5072_50720601_27_dialog_content = "Namun, kemampuan saya agak terbatas dalam kasus ini, yang juga mempengaruhi penilaian saya.",
  ui_story_5072_50720601_28_dialog_content = "Bukan maksudku untuk membuat alarm palsu. Semoga kamu mengerti...",
  ui_story_5072_50720601_29_dialog_content = "Aku setuju. Mungkin tidak enak rasanya berbaring di dalam ruangan gelap yang sempit, aku bayangkan.",
  ui_story_5072_50720601_30_dialog_content = "Namun, aku masih tidak bisa percaya bahkan sekarang...",
  ui_story_5072_50720601_31_dialog_content = "Kita sudah bersama hampir sepanjang hidupku.",
  ui_story_5072_50720601_32_dialog_content = "Siapa yang bisa menduga pedang ajaib yang diam itu tiba-tiba berbicara?",
  ui_story_5072_50720601_33_dialog_content = "Hmm…",
  ui_story_5072_50720601_34_dialog_content = "Saya selalu membayangkanmu sebagai orang yang acuh tak acuh dan serius.",
  ui_story_5072_50720601_35_dialog_content = "Sampai kamu mulai berbicara dan benar-benar membuatku merasa bahwa kamu bukan pedang yang kukenal.",
  ui_story_5072_50720601_36_dialog_content = "Tapi lebih kepada seorang teman yang selalu menjagaku.",
  ui_story_5072_50720601_37_dialog_content = "Mengenai itu... Kemampuan dan kepribadian tidak selalu cocok.",
  ui_story_5072_50720601_38_dialog_content = "Sebagai roh pedang yang baru saja terbangun, mungkin aku dipengaruhi olehmu.",
  ui_story_5072_50720601_39_dialog_content = "Aku? Tidak mungkin, aku tidak sekuat itu. Justru kau yang memiliki pengaruh besar terhadapku.",
  ui_story_5072_50720601_40_dialog_content = "Tidak, bagi saya kamu memang sekuat itu.",
  ui_story_5072_50720601_41_dialog_content = "Karena semua yang aku tahu, aku pelajari darimu.",
  ui_story_5072_50720601_42_dialog_content = "Tujuanku adalah untuk memberitahumu segala hal tentang pedang ini dan membantumu melihat dunia dari perspektifnya.",
  ui_story_5072_50720601_43_dialog_content = "Sebelumnya, saya hanya bisa menonton. Tapi sekarang, akhirnya saya bisa berbicara dan membantu kamu!",
  ui_story_5072_50720601_44_dialog_content = "Saya berharap kita bisa terus saling mengandalkan dan mencari harapan bersama-sama!",
  ui_story_5072_50720601_45_dialog_content = "Wow, tak pernah kusangka akan ada hari dimana aku mendengar dorongan dari pedang sihirku...",
  ui_story_5072_50720601_46_dialog_content = "Terima kasih. Aku merasa jauh lebih baik sekarang. Perasaannya sama...",
  ui_story_5072_50720601_47_dialog_content = "<size=45>Berhenti, pencuri!</size>",
  ui_story_5072_50720601_48_dialog_content = "?!",
  ui_story_5072_50720601_49_dialog_content = "Bukankah itu orang yang kamu bilang harus diwaspadai sebelumnya?",
  ui_story_5072_50720601_50_dialog_content = "Dia memang seorang pencuri... Panggilan yang bagus.",
  ui_story_5072_50720601_51_dialog_content = "Sebenarnya, itu hanya komentar asal saja...",
  ui_story_5072_50720601_52_dialog_content = "Jadi apa yang harus kita lakukan sekarang...?",
  ui_story_5072_50720601_53_dialog_content = "Dia mencoba mencuri dariku dan mungkin menargetkanmu.",
  ui_story_5072_50720601_54_dialog_content = "Kita tidak bisa membiarkan itu begitu saja, jadi tentu saja kita akan menangkapnya.",
  ui_story_5072_50720601_55_dialog_content = "Oke, ayo pergi.",
  ui_story_5072_50720601_56_dialog_content = "Di sini ramai. Aku bisa menangani ini sendiri.",
  ui_story_5072_50720601_57_dialog_content = "Ini hanya seorang pencuri, setelah semua. Aku tidak menghabiskan bertahun-tahun sebagai tentara bayaran untuk apa-apa...",
  ui_story_5072_50720601_58_dialog_content = "Jadi duduk dan tonton... Eh, duduk dan rasakan apa yang akan saya lakukan!",
  ui_story_5072_50720602_1_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5072_50720602_2_dialog_content = "Bukankah kamu diperintahkan untuk berhenti?",
  ui_story_5072_50720602_3_dialog_content = "Ini kamu, wanita yang pernah kutabrak... Aku tidak merasa ada dendam di antara kita.",
  ui_story_5072_50720602_4_dialog_content = "Jadi, tidak bisakah Anda membiarkan saya pergi, mengingat ini adalah pelanggaran pertama saya?",
  ui_story_5072_50720602_5_dialog_content = "Hanya orang-orang yang bisa mengatakan apakah ini pertama kalinya bagi Anda.",
  ui_story_5072_50720602_6_dialog_content = "Juga, saya cukup yakin kamu mencoba mencuri dariku saat itu.",
  ui_story_5072_50720602_7_dialog_content = "Aku bukan tipe orang yang memaafkan semua orang.",
  ui_story_5072_50720602_8_dialog_content = "Hei, bukankah itu pencuri yang sudah berkeliaran selama beberapa hari?",
  ui_story_5072_50720602_9_dialog_content = "Pencuri bodoh, mari kita lihat seberapa cepat kamu bisa lari sekarang!",
  ui_story_5072_50720602_10_dialog_content = "Terima kasih banyak, nona muda.",
  ui_story_5072_50720602_11_dialog_content = "Jangan sebutkan itu. Saya hanya melakukan apa yang harus saya lakukan.",
  ui_story_5072_50720602_12_dialog_content = "Hei lihat, pencurinya telah ditangkap, berkat wanita dari Longzhou!",
  ui_story_5072_50720602_13_dialog_content = "Dia tampak terlalu mungil dan lembut untuk menjadi petarung yang begitu hebat!",
  ui_story_5072_50720602_14_dialog_content = "Anu...",
  ui_story_5072_50720602_15_dialog_content = "(Kerumunan semakin besar dan aku mulai merasa sedikit...)",
  ui_story_5072_50720602_16_dialog_content = "Sebagai tanda terima kasihku, aku ingin mengundangmu ke tokoku!",
  ui_story_5072_50720602_17_dialog_content = "Aku akan menyajikan teh terbaik yang aku punya untukmu...",
  ui_story_5072_50720602_18_dialog_content = "Aduh!",
  ui_story_5072_50720602_19_dialog_content = "Siapa yang baru saja mencolekku?!",
  ui_story_5072_50720602_20_dialog_content = "Apa yang kamu katakan? Tidak ada yang menyentuhmu. Wanita itu adalah satu-satunya yang berada di sampingmu!",
  ui_story_5072_50720602_21_dialog_content = "Tidak apa-apa. Aku tidak akan tinggal. Kamu harus menyerahkan pencuri itu ke Penjaga Kota...",
  ui_story_5072_50720602_22_dialog_content = "A-Aku punya urusan mendesak yang harus kuurus, jadi aku harus pergi.",
  ui_story_5072_50720602_23_dialog_content = "Hei, tunggu, gadis muda...",
  ui_story_5072_50720602_24_dialog_content = "Selamat tinggal!",
  ui_story_5072_50720602_25_dialog_content = "Fiuh…",
  ui_story_5072_50720602_26_dialog_content = "Saya begitu terbiasa dengan kostum ini, saya lupa tentang duri-duri di tubuhku.",
  ui_story_5072_50720602_27_dialog_content = "Saya harus ingat untuk menjaga jarak dari orang lain.",
  ui_story_5072_50720602_28_dialog_content = "Maaf...",
  ui_story_5072_50720602_29_dialog_content = "Hah? Mengapa kamu meminta maaf, Pedang Sihir?",
  ui_story_5072_50720602_30_dialog_content = "Duri-duri ini adalah salahku karena gagal menemukan cara lain untuk menyembuhkanmu.",
  ui_story_5072_50720602_31_dialog_content = "Itu dianggap sebagai kelalaian dari diri saya sebagai roh pedang, bukan?",
  ui_story_5072_50720602_32_dialog_content = "Tidak, bagaimana mungkin ini bisa jadi salahmu?",
  ui_story_5072_50720602_33_dialog_content = "Tolong jangan menyalahkan diri sendiri!",
  ui_story_5072_50720602_34_dialog_content = "Duri-duri ini menyelamatkan hidupku dan tidak menambah penderitaanku... Aku tidak punya alasan untuk mengeluh.",
  ui_story_5072_50720602_35_dialog_content = "Saya hanya ingin mematahkan kutukan dan membuat keluarga saya merasa tenang.",
  ui_story_5072_50720602_36_dialog_content = "Arrie...",
  ui_story_5072_50720602_37_dialog_content = "Dan lihat, bahkan masalah tidak bisa memakai gaun yang bagus bukanlah masalah di Twin Pavilions Bay.",
  ui_story_5072_50720602_38_dialog_content = "Ya, gaun itu tampak sangat bagus padamu.",
  ui_story_5072_50720602_39_dialog_content = "Kamu juga, Pedang Ajaib...? Oke, cukup tentang itu.",
  ui_story_5072_50720602_40_dialog_content = "(Jujur, saya juga suka seperti ini...)",
  ui_story_5072_50720602_41_dialog_content = "Sekarang bukan waktunya menikmati kehidupan sosialita. Kita harus pergi bertemu dengan Nona Armilla sebelum kita terlambat.",
  ui_story_5072_50720602_42_dialog_content = "Sebagai seorang tentara bayaran, saya harus tetap waspada setiap saat.",
  ui_story_5072_50720701_1_dialog_content = "Aku di sini, Arrie.",
  ui_story_5072_50720701_2_dialog_content = "?!",
  ui_story_5072_50720701_3_dialog_content = "Nona Armilla! Wah, syukurlah, aku pikir aku akan terlambat.",
  ui_story_5072_50720701_4_dialog_content = "Tidak apa-apa. Saya baru saja sampai di sini sendiri, dan dengan kabar baik pula.",
  ui_story_5072_50720701_5_dialog_content = "Semua berkat petunjuk yang kamu dapatkan.",
  ui_story_5072_50720701_6_dialog_content = "Apakah kamu merujuk pada Tuan Rumah Vilanor?",
  ui_story_5072_50720701_7_dialog_content = "Ya. Yang patut dirayakan adalah fakta bahwa saya telah memecahkan misteri terbesar yang mengelilinginya.",
  ui_story_5072_50720701_8_dialog_content = "Secara khusus, bagaimana seorang pelayan biasa bisa terlalu kuat untuk Anda tangani.",
  ui_story_5072_50720701_9_dialog_content = "Pedanglah penyebab dari semua ini!",
  ui_story_5072_50720701_10_dialog_content = "Anggota Red Shell mengatakan mereka pernah melihat pedang itu sebelumnya. Itu adalah bilah yang indah dari Longzhou.",
  ui_story_5072_50720701_11_dialog_content = "Pedang ini pasti terpesona dan tepat barang yang ingin saya ambil kembali!",
  ui_story_5072_50720701_12_dialog_content = "Cerita ini juga mencerminkan bagaimana roda gigi saling terhubung dalam sebuah gadget...",
  ui_story_5072_50720701_13_dialog_content = "Sebuah pedang arcane?",
  ui_story_5072_50720701_14_dialog_content = "Tapi bukankah itu membutuhkan keahlian tinggi dari pengguna untuk menggunakannya?",
  ui_story_5072_50720701_15_dialog_content = "Pertanyaan yang bagus, Arrie, dan itulah yang membuat pedang ini unik.",
  ui_story_5072_50720701_16_dialog_content = "Jika pedangmu dirancang khusus untuk digunakan hanya olehmu...",
  ui_story_5072_50720701_17_dialog_content = "Lalu pedang ini dibuat khusus untuk siapa saja yang ingin menggunakannya.",
  ui_story_5072_50720701_18_dialog_content = "Jadi bahkan mereka yang tidak memiliki keterampilan bertarung bisa membela diri mereka sendiri.",
  ui_story_5072_50720701_19_dialog_content = "Tapi jelas, ini bisa menimbulkan masalah yang jauh lebih menakutkan...",
  ui_story_5072_50720701_20_dialog_content = "Di tangan orang lemah, itu adalah perlindungan. Tapi di tangan orang kasar...",
  ui_story_5072_50720701_21_dialog_content = "Ya, itu akan menjadikannya sebagai senjata pembunuhan.",
  ui_story_5072_50720701_22_dialog_content = "Oh, begitu…",
  ui_story_5072_50720701_23_dialog_content = "Itu adalah satu pedang yang menyedihkan dan dieksploitasi.",
  ui_story_5072_50720701_24_dialog_content = "Pembuatnya mungkin terlalu tenggelam dalam visinya hingga tidak bisa memprediksi sesuatu seperti ini...",
  ui_story_5072_50720701_25_dialog_content = "Saya sudah melaporkan situasi dan risiko ke Lins dan markas besar.",
  ui_story_5072_50720701_26_dialog_content = "Jadi mereka akan mengetahui tentang Vilanor's Host dan otak potensial di baliknya.",
  ui_story_5072_50720701_27_dialog_content = "Serangan malam tidak seharusnya menjadi kejadian rutin lagi.",
  ui_story_5072_50720701_28_dialog_content = "Itu menjelaskan poster hadiah yang saya lihat. Anda yang memberi tahu mereka tentang itu.",
  ui_story_5072_50720701_29_dialog_content = "Aku harus meningkatkan usahaku agar tidak tertinggal!",
  ui_story_5072_50720701_30_dialog_content = "Ayolah, jangan terlalu tegang.",
  ui_story_5072_50720701_31_dialog_content = "Aku tak bisa melakukannya tanpa usahamu.",
  ui_story_5072_50720701_32_dialog_content = "Kamu hanya perlu terus melakukan apa yang telah kamu lakukan. Kita akan mengunjungi petunjuk berikutnya dalam beberapa hari ke depan.",
  ui_story_5072_50720701_33_dialog_content = "Tapi mari kita tidak memukul semak-semak dan menakuti ular itu.",
  ui_story_5072_50720701_34_dialog_content = "Ular apa...?",
  ui_story_5072_50720701_35_dialog_content = "Ular?",
  ui_story_5072_50720701_36_dialog_content = "Oh, itu hanya ungkapan, tapi aku tahu tempat yang harus aku bawa kamu ke sana sekarang.",
  ui_story_5072_50720701_37_dialog_content = "Di mana?",
  ui_story_5072_50720701_38_dialog_content = "Seorang apoteker, dengan setiap ramuan obat di bawah matahari dan herbalis teratas.",
  ui_story_5072_50720701_39_dialog_content = "Izinkan saya membawa wanita saya ke sana dan mendapatkan pengobatan di sana.",
  ui_story_5072_50720701_40_dialog_content = "Uh, anu...",
  ui_story_5072_50720701_41_dialog_content = "Maaf, saya menemui seorang pencuri dan tidak bisa menahan diri.",
  ui_story_5072_50720701_42_dialog_content = "Itu bukan sesuatu yang perlu kamu rasakan bersalah. Itu membuatmu lebih dari sekedar tentara bayaran. Itu membuatmu menjadi pahlawan.",
  ui_story_5072_50720701_43_dialog_content = "Kamu membuatku tersanjung. Aku khawatir kostum yang kamu berikan untukku ini mungkin akan rusak...",
  ui_story_5072_50720701_44_dialog_content = "Jangan khawatir tentang itu. Barang-barang rusak itu hal yang biasa. Belum lagi ada penjahit dekat dengan apotek.",
  ui_story_5072_50720701_45_dialog_content = "Juga, kami memiliki banyak perbekalan cadangan.",
  ui_story_5072_50720701_46_dialog_content = "Anda adalah sosialita Longzhou, setelah semua, dan pantas mendapatkan lebih dari satu pakaian.",
  ui_story_5072_50720701_47_dialog_content = "Ayo, mari kita pergi belanja di Jalan Chunxi.",
  ui_story_5072_50720701_48_dialog_content = "Oke, cukup.",
  ui_story_5072_50720701_49_dialog_content = "Selamat datang! Ada yang bisa saya bantu... Oh, kamu rupanya.",
  ui_story_5072_50720701_50_dialog_content = "Apakah kamu mencoba mengatakan bahwa aku tidak diterima di sini?",
  ui_story_5072_50720701_51_dialog_content = "Master tidak ada hari ini. Saya bisa memberi Anda diskon reguler jika Anda ingin bahan dasar untuk membuat minuman herbal. Jangan membuatnya sulit untuk saya.",
  ui_story_5072_50720701_52_dialog_content = "Kamu mengatakannya seolah-olah aku selalu memanfaatkanmu setiap saat.",
  ui_story_5072_50720701_53_dialog_content = "Nah, kamu selalu menemukan cara untuk menawar segalanya menjadi lebih murah.",
  ui_story_5072_50720701_54_dialog_content = "Jauh lebih mudah bagiku untuk segera menyingkirkanmu.",
  ui_story_5072_50720701_55_dialog_content = "Baik, kamu sudah menyampaikan maksudmu. Aku tidak datang untuk sesuatu yang istimewa hari ini.",
  ui_story_5072_50720701_56_dialog_content = "Dan bukan saya yang membutuhkan perhatian medis. Ini wanita di samping saya ini.",
  ui_story_5072_50720701_57_dialog_content = "Wanita ini terbiasa dengan barang-barang mewah, jadi pastikan kamu menunjukkan stok berkualitas!",
  ui_story_5072_50720701_58_dialog_content = "Saya tidak akan pelit pada pendatang baru.",
  ui_story_5072_50720701_59_dialog_content = "Merusak reputasiku sendiri bukanlah masalah besar, tetapi merusak reputasi tuanku adalah.",
  ui_story_5072_50720701_60_dialog_content = "Oh, dan pasiennya...",
  ui_story_5072_50720701_61_dialog_content = "Bagaimana dengan saya...?",
  ui_story_5072_50720701_62_dialog_content = "Hei, bolehkah aku berbicara denganmu secara pribadi?",
  ui_story_5072_50720701_63_dialog_content = "Tidak apa-apa. Utarakan saja pikiranmu.",
  ui_story_5072_50720701_64_dialog_content = "Cedera pada wanita ini bukanlah hal yang biasa tetapi kondisi kronis selama bertahun-tahun...",
  ui_story_5072_50720701_65_dialog_content = "Itu mewujudkan kebencian yang sangat kuat.",
  ui_story_5072_50720701_66_dialog_content = "Mungkin sebuah keajaiban bagi dia untuk masih hidup dengan benda itu.",
  ui_story_5072_50720701_67_dialog_content = "Siapa dia...",
  ui_story_5072_50720701_68_dialog_content = "Sangat tidak sopan untuk melanjutkan pertanyaan seperti itu.",
  ui_story_5072_50720701_69_dialog_content = "Oke, paham itu.",
  ui_story_5072_50720701_70_dialog_content = "Tetapi ini bukan masalah yang bisa diatasi oleh obat biasa, selain meredakan sedikit rasa sakit di kulit.",
  ui_story_5072_50720701_71_dialog_content = "Maaf, nona muda.",
  ui_story_5072_50720701_72_dialog_content = "Tidak apa-apa. Terima kasih atas diagnosanya.",
  ui_story_5072_50720701_73_dialog_content = "Aku sudah terbiasa dengan tubuh ini, dan aku sangat berterima kasih untuk pakaian dan obat-obatan.",
  ui_story_5072_50720701_74_dialog_content = "Budaya Longzhou benar-benar luar biasa.",
  ui_story_5072_50720701_75_dialog_content = "Tapi bukankah kamu berasal dari Longzhou...?",
  ui_story_5072_50720701_76_dialog_content = "Jangan khawatir tentang itu dan siapkan herbalnya! Ngomong-ngomong, saya juga butuh daftar.",
  ui_story_5072_50720701_77_dialog_content = "Bukankah kamu baru saja berjanji tidak akan menawar atau memanfaatkan saya?",
  ui_story_5072_50720701_78_dialog_content = "Aku hanya melakukan ini karena kamu membawakan pasien baru untukku... Baiklah, daftar jenis apa?",
  ui_story_5072_50720701_79_dialog_content = "Nama-nama korban yang baru-baru ini ditusuk. Semakin detail, semakin baik.",
  ui_story_5072_50720701_80_dialog_content = "...",
  ui_story_5072_50720701_81_dialog_content = "Baiklah, tapi mengumpulkan daftar dan jamu ini akan memakan waktu.",
  ui_story_5072_50720701_82_dialog_content = "Sebagai balasannya, kenapa kamu tidak pergi mengurus tikus-tikus dari air?",
  ui_story_5072_50720701_83_dialog_content = "Tikus? Bukankah seharusnya kau yang menyajikan teh untuk kami?",
  ui_story_5072_50720701_84_dialog_content = "Tentu saja... TIDAK!",
  ui_story_5072_50720702_1_dialog_content = "Kami mendapatkan obat, pakaian baru, dan yang paling penting, daftarnya.",
  ui_story_5072_50720702_2_dialog_content = "Semuanya pasti berjalan lancar saat kamu ada di sekitar, Arrie.",
  ui_story_5072_50720702_3_dialog_content = "Tapi aku tidak melakukan apa-apa sama sekali... Malah, kamu yang melakukan segalanya untukku.",
  ui_story_5072_50720702_4_dialog_content = "Tidak, tidak, seperti biasa kamu tampil dengan sangat baik.",
  ui_story_5072_50720702_5_dialog_content = "Sungguh?",
  ui_story_5072_50720702_6_dialog_content = "Kalau tidak, murid itu pasti akan menendang saya keluar dari toko.",
  ui_story_5072_50720702_7_dialog_content = "Kita akan membicarakan itu nanti. Ayo lihat daftarnya.",
  ui_story_5072_50720702_8_dialog_content = "Kamu jauh lebih ahli dengan pedang daripada aku, jadi aku ingin pendapatmu.",
  ui_story_5072_50720702_9_dialog_content = "Baiklah…",
  ui_story_5072_50720702_10_dialog_content = "Hmm…",
  ui_story_5072_50720702_11_dialog_content = "Ini sangat rinci. Tidak heran dia informan terpercaya Anda.",
  ui_story_5072_50720702_12_dialog_content = "Murid itu juga luar biasa.",
  ui_story_5072_50720702_13_dialog_content = "Dia mungkin terlihat muda, tapi sangat berpengetahuan dan merupakan dokter yang hebat.",
  ui_story_5072_50720702_14_dialog_content = "Dia selalu berbicara tentang menyelamatkan nyawa dan membantu orang sakit. Dia bertekad untuk menyembuhkan seluruh dunia.",
  ui_story_5072_50720702_15_dialog_content = "Sembuhkan apa?",
  ui_story_5072_50720702_16_dialog_content = "Sembuhkan kamu, Nona.",
  ui_story_5072_50720702_17_dialog_content = "Tak usah, kita ngelantur. Cukup periksa sisa daftar tersebut.",
  ui_story_5072_50720702_18_dialog_content = "Oke.",
  ui_story_5072_50720702_19_dialog_content = "Dari daftar ini, saya melihat beberapa pelaut yang bekerja di dermaga baru-baru ini ditikam.",
  ui_story_5072_50720702_20_dialog_content = "Mereka bahkan tidak bisa menjelaskan apa yang terjadi pada mereka selain kejang, pingsan, atau aura hitam di sekitar wajah mereka.",
  ui_story_5072_50720702_21_dialog_content = "Itu sangat mirip dengan yang saya lihat di rumah kolektor itu.",
  ui_story_5072_50720702_22_dialog_content = "Tuan rumah Vilanor kemungkinan besar di balik semua ini. Jadi, mungkin dia aktif di bagian kota itu?",
  ui_story_5072_50720702_23_dialog_content = "Kita berada di halaman yang sama.",
  ui_story_5072_50720702_24_dialog_content = "Barang-barang Longzhou biasanya dikirim melalui jalur air.",
  ui_story_5072_50720702_25_dialog_content = "Kita perlu bertanya kepada para pelaut yang berlayar di Sungai Emas.",
  ui_story_5072_50720702_26_dialog_content = "Karena kita akan mengambil rute itu, kenapa kita tidak menargetkan ikan besar?",
  ui_story_5072_50720702_27_dialog_content = "Tentu. Jadi, apa target kita selanjutnya?",
  ui_story_5072_50720702_28_dialog_content = "Galley Gold River yang disukai oleh pedagang kaya.",
  ui_story_5072_50720702_29_dialog_content = "Haruskah aku menyelinap masuk?",
  ui_story_5072_50720702_30_dialog_content = "Tidak-tidak. Jangan lupa kamu sekarang adalah sosialita dari Longzhou.",
  ui_story_5072_50720702_31_dialog_content = "Sangat wajar bagi Anda untuk merekrut beberapa staf dan pergi ke sana dengan yacht.",
  ui_story_5072_50720702_32_dialog_content = "Apakah itu perlu?",
  ui_story_5072_50720702_33_dialog_content = "Tentu saja. Jika kamu bisa masuk, itu berarti kita dekat dengan sumber pasar gelap.",
  ui_story_5072_50720702_34_dialog_content = "Dan siapapun yang bekerja untuk Tuan Rumah Vilanor pasti kaya atau bergengsi.",
  ui_story_5072_50720702_35_dialog_content = "Mengingat dapur kapal adalah tempat populer bagi kalangan atas, menyamar di sana sama sulitnya dengan mencari jarum di tumpukan jerami.",
  ui_story_5072_50720702_36_dialog_content = "Lebih baik bagi kita untuk menawarkan petunjuk atau kekayaan dan memancing ular keluar.",
  ui_story_5072_50720702_37_dialog_content = "Pancing ular itu keluar...",
  ui_story_5072_50720702_38_dialog_content = "Terus kenapa?",
  ui_story_5072_50720702_39_dialog_content = "Saya merasa Anda memiliki kecintaan pada ular.",
  ui_story_5072_50720702_40_dialog_content = "Nah, eh...",
  ui_story_5072_50720703_1_dialog_content = "...",
  ui_story_5072_50720703_2_dialog_content = "Ehem, apakah pemiliknya ada di sini?",
  ui_story_5072_50720703_3_dialog_content = "Ini saya datang... Hei, apa yang bisa saya bantu, wanita muda?",
  ui_story_5072_50720703_4_dialog_content = "Apakah ini kapal yang akan membawa saya ke Galley Gold River?",
  ui_story_5072_50720703_5_dialog_content = "Kamu telah datang ke tempat yang tepat. Ini adalah kendaraan tercepat untuk itu.",
  ui_story_5072_50720703_6_dialog_content = "Tapi...",
  ui_story_5072_50720703_7_dialog_content = "Memangnya kenapa?",
  ui_story_5072_50720703_8_dialog_content = "Patron kaya dan pesta mereka sering memilih untuk menyewa kapal untuk acara mereka.",
  ui_story_5072_50720703_9_dialog_content = "Ini akan menjadi penantian bagi penumpang biasa.",
  ui_story_5072_50720703_10_dialog_content = "Beraninya kau menyiratkan bahwa saya tidak mampu membayar layananmu!",
  ui_story_5072_50720703_11_dialog_content = "Saya tidak bisa percaya betapa kasarnya orang-orang di Twin Pavilions Bay...",
  ui_story_5072_50720703_12_dialog_content = "Tidak-tidak, bukan itu yang saya maksud.",
  ui_story_5072_50720703_13_dialog_content = "Kamu berpakaian mewah, tapi sendirian.",
  ui_story_5072_50720703_14_dialog_content = "Ada banyak operator tidak bermoral di dermaga ini yang hanya mencari keuntungan.",
  ui_story_5072_50720703_15_dialog_content = "Tapi kami mempertaruhkan reputasi kami pada keadilan dan kepercayaan.",
  ui_story_5072_50720703_16_dialog_content = "Selain memberikan penawaran harga yang wajar, saya bisa mencari kru yang dapat dipercaya dan aman.",
  ui_story_5072_50720703_17_dialog_content = "Kita sepakat?",
  ui_story_5072_50720703_18_dialog_content = "Saya suka cara Anda berpikir.",
  ui_story_5072_50720703_19_dialog_content = "Aku tidak peduli dengan apapun kecuali sikap.",
  ui_story_5072_50720703_20_dialog_content = "Lakukan apa saja yang harus Anda lakukan.",
  ui_story_5072_50720703_21_dialog_content = "Aku akan segera melakukannya.",
  ui_story_5072_50720703_22_dialog_content = "Ada pekerjaan untuk kalian, pelaut!",
  ui_story_5072_50720703_23_dialog_content = "Iya!",
  ui_story_5072_50720801_1_dialog_content = "Apakah kabin ini nyaman untuk Anda, Nona?",
  ui_story_5072_50720801_2_dialog_content = "Ini cukup memadai.",
  ui_story_5072_50720801_3_dialog_content = "Para pendayung akan memberikan segalanya yang mereka miliki untuk mengantarmu tepat waktu!",
  ui_story_5072_50720801_4_dialog_content = "Kalau kamu bisa memberi sedikit insentif, kami bisa berjalan lebih cepat...",
  ui_story_5072_50720801_5_dialog_content = "Nah, kecepatan bukan segalanya, dan saya tidak yakin apakah kapal Anda cukup dibangun untuk itu.",
  ui_story_5072_50720801_6_dialog_content = "Itu seharusnya bukan masalah.",
  ui_story_5072_50720801_7_dialog_content = "Kru kami memiliki pengalaman selama belasan tahun. Keamanan Anda terjamin.",
  ui_story_5072_50720801_8_dialog_content = "Bukan masalah?",
  ui_story_5072_50720801_9_dialog_content = "Apakah kamu pikir saya tidak tahu bahwa banyak pelaut telah terluka oleh Tuan Rumah Vilanor akhir-akhir ini?",
  ui_story_5072_50720801_10_dialog_content = "Saya berasumsi saat ini ada kekurangan orang yang dapat diandalkan.",
  ui_story_5072_50720801_11_dialog_content = "Wow, sumber informasimu bagus.",
  ui_story_5072_50720801_12_dialog_content = "Tapi yang tidak Anda sadari adalah Teluk ini tidak pernah kekurangan pelaut.",
  ui_story_5072_50720801_13_dialog_content = "Dan masalah Vilanor's Host tidak membuat cela sedikitpun pada hal itu.",
  ui_story_5072_50720801_14_dialog_content = "Tidak ada penyok? Jadi Anda tidak khawatir dia kembali dan merusak bisnis di dermaga?",
  ui_story_5072_50720801_15_dialog_content = "Jangan khawatir, Nyonya. Dia belum menampakkan dirinya lagi sejak malam itu.",
  ui_story_5072_50720801_16_dialog_content = "Masalah sebenarnya di balik semua itu adalah, para pejabat besar membuang barang-barang ke pasar gelap.",
  ui_story_5072_50720801_17_dialog_content = "Banyak dari mereka berurusan dengan bajak laut atau penjahat.",
  ui_story_5072_50720801_18_dialog_content = "Mereka bisa melakukan apa saja selama guild membiarkan, dan membuat sulit bagi kita yang menjalankan bisnis secara sah.",
  ui_story_5072_50720801_19_dialog_content = "Kapal terbaru di Sungai Emas dibeli oleh salah satu orang penting.",
  ui_story_5072_50720801_20_dialog_content = "Rumor mengatakan dia juga memiliki dapur mewah itu.",
  ui_story_5072_50720801_21_dialog_content = "Huh...",
  ui_story_5072_50720801_22_dialog_content = "Apa yang membuatmu berdesah?",
  ui_story_5072_50720801_23_dialog_content = "Bagi saya, kapalnya jauh lebih rendah daripada kapal Lins' dan tidak begitu baik.",
  ui_story_5072_50720801_24_dialog_content = "Oh, Nyonya. Ini hanya kapal penumpang. Bagaimana mereka bisa menyaingi kapal kargo laut milik Lin?",
  ui_story_5072_50720801_25_dialog_content = "Tapi untuk perahu kecil seperti milikku, itu masih di luar jangkauan kami.",
  ui_story_5072_50720801_26_dialog_content = "Mereka tidak bisa melawan Lins, tetapi mereka pasti memiliki cukup banyak untuk mengganggu kita yang lemah ini.",
  ui_story_5072_50720801_27_dialog_content = "Bagaimana mereka melakukannya?",
  ui_story_5072_50720801_28_dialog_content = "Uang perlindungan, tentu saja; konon untuk menjaga perahu kita aman dari Eclipsites.",
  ui_story_5072_50720801_29_dialog_content = "Kami akhirnya membayar lebih dan lebih banyak tetapi masih tidak melihat satu Eclipsite pun berkurang.",
  ui_story_5072_50720801_30_dialog_content = "Aku mulai berpikir mereka bekerja sama!",
  ui_story_5072_50720801_31_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5072_50720801_32_dialog_content = "Apa itu? Jangan bilang kita menabrak kapal lain di siang bolong!",
  ui_story_5072_50720801_33_dialog_content = "Jangan khawatir, Lady. Ini hanya situasi kecil, saya yakin. Mari saya lihat.",
  ui_story_5072_50720801_34_dialog_content = "Hati-hati, Arrie. Eclipsites akan datang.",
  ui_story_5072_50720801_35_dialog_content = "Eclipsite yang bersembunyi di Sungai Emas...?",
  ui_story_5072_50720801_36_dialog_content = "Hei, jangan mendekat... Ah—",
  ui_story_5072_50720801_37_dialog_content = "<color=#e8d9bb>Guyuran!</color>",
  ui_story_5072_50720801_38_dialog_content = "Kita harus menyelamatkannya.",
  ui_story_5072_50720801_39_dialog_content = "Aku tahu. Bantu aku, Pedang Ajaib.",
  ui_story_5072_50720802_1_dialog_content = "Pegangan yang kencang!",
  ui_story_5072_50720802_2_dialog_content = "Oh, terima kasih...",
  ui_story_5072_50720802_3_dialog_content = "Heh, heh...",
  ui_story_5072_50720802_4_dialog_content = "Terima kasih atas bantuannya! Eclipsites ini menjijikkan. Kita harus berbalik sekarang...",
  ui_story_5072_50720802_5_dialog_content = "Hei, kemana perginya Eclipsites?",
  ui_story_5072_50720802_6_dialog_content = "Aku membuang mereka semua.",
  ui_story_5072_50720802_7_dialog_content = "Astaga! Kamu melakukan semua itu sendiri?!",
  ui_story_5072_50720802_8_dialog_content = "Terima kasih! Kapal saya, hidup saya, segalanya akan hilang tanpa kamu!",
  ui_story_5072_50720802_9_dialog_content = "Sama-sama, dan mari kita tidak berbalik. Aku masih mengandalkanmu untuk mengantarku ke dapur.",
  ui_story_5072_50720802_10_dialog_content = "Ya, ya, tentu saja. Ini hanya...",
  ui_story_5072_50720802_11_dialog_content = "Kamu bertarung dengan baik untuk seorang gadis kecil, my lady.",
  ui_story_5072_50720802_12_dialog_content = "...",
  ui_story_5072_50720802_13_dialog_content = "Dan di dalam kotak itu bukan alat musik...",
  ui_story_5072_50720802_14_dialog_content = "Tapi sebuah pedang besar, hitam seperti yang digosipkan—",
  ui_story_5072_50720802_15_dialog_content = "Tidak, tidak, maksudku, ini benar-benar pengalaman yang membuka mata.",
  ui_story_5072_50720802_16_dialog_content = "...",
  ui_story_5072_50720802_17_dialog_content = "Tapi, eh, kamu langsung bertanya tentang Vilanor's Host begitu naik ke kapal...",
  ui_story_5072_50720802_18_dialog_content = "Apa yang Anda maksudkan?",
  ui_story_5072_50720802_19_dialog_content = "Bukan apa-apa!",
  ui_story_5072_50720802_20_dialog_content = "Kamu telah menyelamatkan hidupku dan di sini aku meragukanmu. Itu tidak benar...",
  ui_story_5072_50720802_21_dialog_content = "Bagaimana bisa kau begitu brutal, tak berbelas kasihan, Tuan Vilanor, benar?",
  ui_story_5072_50720802_22_dialog_content = "Tentu saja bukan.",
  ui_story_5072_50720802_23_dialog_content = "Pedang ini... adalah pusaka keluarga! Aku akan membawanya ke galeri untuk ditaksir.",
  ui_story_5072_50720802_24_dialog_content = "Seharusnya aku tidak menunjukkannya, tapi situasinya sangat genting...",
  ui_story_5072_50720802_25_dialog_content = "Anda akan dibayar penuh untuk layanan Anda, dan keamanan Anda dijamin untuk sisa perjalanan ini.",
  ui_story_5072_50720802_26_dialog_content = "Hanya fokus untuk membawa saya ke tujuan saya!",
  ui_story_5072_50720802_27_dialog_content = "S-Siap! Silakan duduk di kabin Anda dan kami akan segera datang!",
  ui_story_5072_50720901_1_dialog_content = "Ini dia! Dapur, gadisku.",
  ui_story_5072_50720901_2_dialog_content = "Cukup pergi ke atas dan akan ada seseorang yang siap membantu Anda.",
  ui_story_5072_50720901_3_dialog_content = "Saya rasa itu tidak perlu, karena kau pasti lebih paham protokolnya daripada aku.",
  ui_story_5072_50720901_4_dialog_content = "Tidak masalah. Terima kasih untuk arahannya.",
  ui_story_5072_50720901_5_dialog_content = "Jadi ini adalah Galeri Sungai Emas... Pasti tempat yang sangat ramai.",
  ui_story_5072_50720901_6_dialog_content = "Atau mungkin lebih tepatnya, kantong campuran? Saya merasakan banyak hal yang berbeda.",
  ui_story_5072_50720901_7_dialog_content = "Sampai saat ini, saya tidak dapat mengkonfirmasi apakah Tuan Rumah Vilanor memiliki hubungan apa pun dengan di sini.",
  ui_story_5072_50720901_8_dialog_content = "Mengerti. Terima kasih, aku akan berhati-hati.",
  ui_story_5072_50720901_9_dialog_content = "Dan saya juga mengerjakan PR sebelum datang.",
  ui_story_5072_50720901_10_dialog_content = "Apa yang kamu katakan tentang Vilanor yang mengendalikan bayangan dan energi, Arrie...",
  ui_story_5072_50720901_11_dialog_content = "Dugaan saya, dia mungkin meninggalkan jejak pada barang-barang tertentu, seperti alat makan yang disentuh.",
  ui_story_5072_50720901_12_dialog_content = "Barang antik yang bergerak itu memancarkan aura hitam...",
  ui_story_5072_50720901_13_dialog_content = "Mereka mungkin telah terpesona oleh Vilanor.",
  ui_story_5072_50720901_14_dialog_content = "Ini semacam tanda tangan?",
  ui_story_5072_50720901_15_dialog_content = "Dalam hal ini, pertemuan Galley Sungai Emas jauh lebih dari apa yang tampak oleh mata.",
  ui_story_5072_50720901_16_dialog_content = "Apa yang tampak oleh mata...?",
  ui_story_5072_50720901_17_dialog_content = "Ya. Jika Tuan Rumah Vilanor adalah penegak eksklusif untuk dalang...",
  ui_story_5072_50720901_18_dialog_content = "Dia mungkin akan mencoba mengalahkan kita untuk mendapatkan relik Longzhou yang dijual.",
  ui_story_5072_50720901_19_dialog_content = "Hapus petunjuk sehingga tidak ada yang bisa mengikuti.",
  ui_story_5072_50720901_20_dialog_content = "Bagaimanapun, dia telah bekerja di Twin Pavilions Bay untuk waktu yang lama.",
  ui_story_5072_50720901_21_dialog_content = "Tidak ada orang luar yang bisa memahami seberapa dalamnya, tidak peduli seberapa banyak dukungan yang mereka dapatkan dari keluarga Lin dan markas besar.",
  ui_story_5072_50720901_22_dialog_content = "Setelah semuanya berlalu dan dilupakan, dia bisa muncul kembali di pasar gelap.",
  ui_story_5072_50720901_23_dialog_content = "Jadi, kamu percaya bahwa Tuan Rumah Vilanor akan berada di dapur?!",
  ui_story_5072_50720901_24_dialog_content = "Ya, dan mungkin juga siapa pun yang menjual pedang ke Twin Pavilions Bay. Saya perlu mengonfirmasi itu...",
  ui_story_5072_50720901_25_dialog_content = "Terima kasih, para hadirin, telah meluangkan waktu dari jadwal sibuk Anda untuk naik ke Galley Gold River saya.",
  ui_story_5072_50720901_26_dialog_content = "Kami memiliki barang koleksi baru untuk Anda nilai dan beli. Jangan ragu untuk menentukan harga.",
  ui_story_5072_50720901_27_dialog_content = "Tapi, aku punya satu permintaan pribadi, dan aku berharap kalian semua bisa membantu...",
  ui_story_5072_50720901_28_dialog_content = "Baru-baru ini saya kehilangan sebuah relik yang berharga. Itu adalah pedang ajaib dari luar negeri...",
  ui_story_5072_50720901_29_dialog_content = "...!!!",
  ui_story_5072_50720901_30_dialog_content = "Pedang ini sangat rumit, untuk itu saya menghabiskan banyak uang untuk mendapatkannya.",
  ui_story_5072_50720901_31_dialog_content = "Sayangnya, aku bahkan tidak sempat mengayunkannya sebelum aku kehilangannya. Oleh karena itu...",
  ui_story_5072_50720901_32_dialog_content = "Aku harus memajukan pertemuan ini dengan harapan mendapatkan petunjuk dari kamu.",
  ui_story_5072_50720901_33_dialog_content = "...",
  ui_story_5072_50720901_34_dialog_content = "<size=30>Pedang Arcane? Bukankah itu bentuk asli dari Vilanor yang dideskripsikan oleh Miss Armilla?</size>",
  ui_story_5072_50720901_35_dialog_content = "<size=30>Saya harus mencari tahu lebih banyak!</size>",
  ui_story_5072_50720901_36_dialog_content = "Tuan, apakah Anda mendengar tentang penusukan terbaru oleh Vilanor's Host di Twin Pavilions Bay?",
  ui_story_5072_50720901_37_dialog_content = "Maksudmu insiden kolektor Lumopolis? Aku sudah mendengar satu dua hal tentang itu.",
  ui_story_5072_50720901_38_dialog_content = "Tapi apa hubungannya dia dengan pedang ajaibku?",
  ui_story_5072_50720901_39_dialog_content = "Anda kehilangan pedang hanya untuk memiliki pendekar pedang yang kejam muncul di Twin Pavilions Bay.",
  ui_story_5072_50720901_40_dialog_content = "Jika dia menggunakan pedangmu, bukankah kamu juga akan sedikit bertanggung jawab?",
  ui_story_5072_50720901_41_dialog_content = "Nyonya, pedangku hanyalah barang koleksi.",
  ui_story_5072_50720901_42_dialog_content = "Saya membelinya dengan harga yang mahal hanya karena rasa penasaran. Saya adalah korban dalam kerugian ini.",
  ui_story_5072_50720901_43_dialog_content = "Dan tuan rumah Vilanor itu hanya menyakiti orang karena dia sendiri jahat.",
  ui_story_5072_50720901_44_dialog_content = "Tidak ada bedanya apakah dia menggunakan pedang misterius, rapier, atau pedang besar, mengerti?",
  ui_story_5072_50720901_45_dialog_content = "Benarkah...?",
  ui_story_5072_50720901_46_dialog_content = "Ini dia.",
  ui_story_5072_50720901_47_dialog_content = "Sangat tidak tertahankan rasa sakit dan kebencian... Apa yang telah terjadi...?",
  ui_story_5072_50720901_48_dialog_content = "Dari kekuatan kuno di dalamnya, lahirlah pedang terkutuk...",
  ui_story_5072_50720901_49_dialog_content = "Kemungkinan kejahatan ini jauh melampaui apa pun yang bisa kau bayangkan.",
  ui_story_5072_50720901_50_dialog_content = "Atau apakah Anda berniat untuk melacak setiap orang yang mengetahui keberadaan Tuan Rumah Vilanor...",
  ui_story_5072_50720901_51_dialog_content = "Dan singkirkan semuanya untuk menutupi jejakmu sendiri?",
  ui_story_5072_50720901_52_dialog_content = "Kenapa kamu mencemarkan nama baikku? Siapa kamu? Aku tidak ingat mengundangmu!",
  ui_story_5072_50720901_53_dialog_content = "Penjaga, datang dan usir wanita pembohong ini dari tempat ini!",
  ui_story_5072_50720901_54_dialog_content = "Di mana para penjaga?",
  ui_story_5072_50720901_55_dialog_content = "Ada yang aneh!",
  ui_story_5072_50720901_56_dialog_content = "...",
  ui_story_5072_50721001_1_dialog_content = "Roaar—",
  ui_story_5072_50721001_2_dialog_content = "Siapa kamu? Berani sekali kamu menerobos masuk!",
  ui_story_5072_50721001_3_dialog_content = "Tunggu, bukankah itu pedang arkanaku yang sedang kamu pegang?!",
  ui_story_5072_50721001_4_dialog_content = "Kamu tidak datang ke sini hanya untuk mengembalikannya padaku, 'kan?",
  ui_story_5072_50721001_5_dialog_content = "Ini tuan rumah Vilanor! Dia ada di sini! Aku tahu pemilik galley ada di balik ini...",
  ui_story_5072_50721001_6_dialog_content = "Tidak, ketertarikannya pada pedang terasa cukup polos dan dia tidak menyadari ancaman yang ditimbulkan oleh Vilanor's Host.",
  ui_story_5072_50721001_7_dialog_content = "Tapi apa yang dilakukan Pembawa Acara Vilanor di sini?",
  ui_story_5072_50721001_8_dialog_content = "Balas dendam, ya?",
  ui_story_5072_50721001_9_dialog_content = "Balas dendam?",
  ui_story_5072_50721001_10_dialog_content = "Berhenti! Apa yang kamu inginkan? Pilih saja apa pun di sini dan itu milikmu!",
  ui_story_5072_50721001_11_dialog_content = "Aku... ingin... kamu...",
  ui_story_5072_50721001_12_dialog_content = "Apa...?",
  ui_story_5072_50721001_13_dialog_content = "Awas!",
  ui_story_5072_50721001_14_dialog_content = "Aku ingin kamu mati!",
  ui_story_5072_50721001_15_dialog_content = "Swuuss—!",
  ui_story_5072_50721001_16_dialog_content = "Ugh!",
  ui_story_5072_50721001_17_dialog_content = "Tuan Rumah Vilanor! Ini Tuan Rumah Vilanor!",
  ui_story_5072_50721001_18_dialog_content = "Apa yang harus saya lakukan sekarang...?",
  ui_story_5072_50721001_19_dialog_content = "Aku siap, Arrie!",
  ui_story_5072_50721001_20_dialog_content = "Bayangan gelap tidak bisa mengganggu di sini.",
  ui_story_5072_50721001_21_dialog_content = "Kita bisa mengejutkannya dan menang secara tegas.",
  ui_story_5072_50721001_22_dialog_content = "Mengerti. Aku mengandalkanmu, Magic Sword...",
  ui_story_5072_50721001_23_dialog_content = "Bebek!",
  ui_story_5072_50721001_24_dialog_content = "Swuuss—!",
  ui_story_5072_50721001_25_dialog_content = "Apa... Aduh!",
  ui_story_5072_50721001_26_dialog_content = "Bum!",
  ui_story_5072_50721001_27_dialog_content = "Apa yang terjadi... Sudah berakhir?",
  ui_story_5072_50721001_28_dialog_content = "Tuan Rumah Vilanor yang memiliki hadiah di kepalanya di mana-mana jatuh begitu saja?",
  ui_story_5072_50721001_29_dialog_content = "Ini tidak mungkin se-simple itu. Ini mungkin disetting untuk menaikkan harga pedang!",
  ui_story_5072_50721001_30_dialog_content = "Benar, saya tidak percaya pedang bisa jahat, atau membuat pemegangnya menjadi jahat.",
  ui_story_5072_50721001_31_dialog_content = "Ini hanya pedang misterius asing. Lihat, tidak ada yang jahat tentang itu...",
  ui_story_5072_50721001_32_dialog_content = "Tidak, letakkan itu!",
  ui_story_5072_50721001_33_dialog_content = "Argh! Balas dendam... Balas dendam!",
  ui_story_5072_50721001_34_dialog_content = "Dia kerasukan.",
  ui_story_5072_50721001_35_dialog_content = "Sial!",
  ui_story_5072_50721001_36_dialog_content = "Memang pedang itulah masalahnya! Ada kutukan di atasnya!",
  ui_story_5072_50721001_37_dialog_content = "Siapa pun yang memiliki itu menjadi Tuan Rumah Vilanor!",
  ui_story_5072_50721001_38_dialog_content = "Dan semakin banyak orang yang kerasukan, semakin kuat pula kekuatannya.",
  ui_story_5072_50721001_39_dialog_content = "Apa yang kau lihat... pendekar pedang!",
  ui_story_5072_50721001_40_dialog_content = "Awas, kita mendapat perhatiannya!",
  ui_story_5072_50721001_41_dialog_content = "Klang—!",
  ui_story_5072_50721001_42_dialog_content = "Ugh...",
  ui_story_5072_50721001_43_dialog_content = "Sekarang pukulannya jadi lebih keras.",
  ui_story_5072_50721001_44_dialog_content = "Seakan-akan aku dan pedangku telah membuatnya bersemangat...",
  ui_story_5072_50721001_45_dialog_content = "Klang—!",
  ui_story_5072_50721001_46_dialog_content = "Sebagai pendekar pedang... kau menyedihkan.",
  ui_story_5072_50721001_47_dialog_content = "Jadi seperti aku, kamu bukanlah seorang pendekar pedang...",
  ui_story_5072_50721001_48_dialog_content = "Abaikan dan ayo kita coba lagi!",
  ui_story_5072_50721001_49_dialog_content = "Aduh…!",
  ui_story_5072_50721001_50_dialog_content = "Swuuss— Klang—!",
  ui_story_5072_50721001_51_dialog_content = "Anda tidak bisa menyakiti saya seperti ini.",
  ui_story_5072_50721001_52_dialog_content = "Anda mungkin memiliki kesadaran Anda sendiri, tetapi sebenarnya Anda juga hanya sekedar perantara...",
  ui_story_5072_50721001_53_dialog_content = "Yang dikendalikan oleh pedang, tidak mampu membebaskan kekuatan sebenarnya.",
  ui_story_5072_50721001_54_dialog_content = "Alasan aku tidak bisa mengalahkanmu sekarang adalah karena...",
  ui_story_5072_50721001_55_dialog_content = "(Di sini terlalu ramai untuk mengayunkan pedangku dengan bebas...)",
  ui_story_5072_50721001_56_dialog_content = "(Tapi aku harus menyembunyikan fakta itu atau akan menjadi lebih buruk ketika itu mengambil sandera...)",
  ui_story_5072_50721001_57_dialog_content = "(Apa yang harus dilakukan...)",
  ui_story_5072_50721001_58_dialog_content = "Apa kamu tahu cara berenang, Arrie?",
  ui_story_5072_50721001_59_dialog_content = "Apa? Ya, sedikit... Kamu punya ide, Magic Sword?",
  ui_story_5072_50721001_60_dialog_content = "Saya sudah merencanakan rutenya. Kamu bawa Vilanor's Host di sampan bersamamu.",
  ui_story_5072_50721001_61_dialog_content = "Lalu jatuhkan dia ke dalam air!",
  ui_story_5072_50721001_62_dialog_content = "Tapi jika kamu bukan perenang yang kuat, ini adalah rencana yang sangat berisiko...",
  ui_story_5072_50721001_63_dialog_content = "Terima kasih, tapi aku akan tetap mencoba, karena itu adalah pilihan terbaik yang kita punya.",
  ui_story_5072_50721001_64_dialog_content = "Aku akan menunjukkan kepadamu kekuatan sejati dari Pedang Ajaibku!",
  ui_story_5072_50721001_65_dialog_content = "Ayo, perantara... Kamu hanyalah kerikil di jalan pembalasanku!",
  ui_story_5072_50721002_1_dialog_content = "Serangan Duri!",
  ui_story_5072_50721002_2_dialog_content = "Argh...!",
  ui_story_5072_50721002_3_dialog_content = "Betapa tak terduga.",
  ui_story_5072_50721002_4_dialog_content = "Apakah karena aku belum sepenuhnya terbiasa dengan tubuh baru ini?",
  ui_story_5072_50721002_5_dialog_content = "Menyerah.",
  ui_story_5072_50721002_6_dialog_content = "Atau pukulan berikutnya akan mengirim kamu ke Sungai Emas!",
  ui_story_5072_50721002_7_dialog_content = "Kamu tidak akan bisa memiliki siapa pun setelah kamu tenggelam ke dasar.",
  ui_story_5072_50721002_8_dialog_content = "<color=#e8d9bb>*klang!*</color>",
  ui_story_5072_50721002_9_dialog_content = "Aduh! Argh...",
  ui_story_5072_50721002_10_dialog_content = "Tidak akan menyerah?",
  ui_story_5072_50721002_11_dialog_content = "(Aku mulai... lelah...)",
  ui_story_5072_50721002_12_dialog_content = "Ada apa? Di mana serangan terakhir yang kamu janjikan?",
  ui_story_5072_50721002_13_dialog_content = "Bisakah kamu bertahan, Arrie?",
  ui_story_5072_50721002_14_dialog_content = "Aku akan melindungimu, jadi ayo tangkap dia!",
  ui_story_5072_50721002_15_dialog_content = "Ah...!",
  ui_story_5072_50721002_16_dialog_content = "(Semakin lama pertarungan ini berlangsung, semakin mengerikan kekuatan Vilanor...)",
  ui_story_5072_50721002_17_dialog_content = "(Tanpa bantuan aktif dari Pedang Sihir, aku tidak akan bisa bertahan...)",
  ui_story_5072_50721002_18_dialog_content = "(Ini bukan pertarungan antara Tuan Rumah Vilanor dan saya, tetapi dua pedang.)",
  ui_story_5072_50721002_19_dialog_content = "Tidak, aku tidak bisa menjadi beban bagi Pedang Ajaib.",
  ui_story_5072_50721002_20_dialog_content = "Kamu baik-baik saja, Arrie?",
  ui_story_5072_50721002_21_dialog_content = "Lihat, bukankah itu Tuan Rumah Vilanor?",
  ui_story_5072_50721002_22_dialog_content = "Apa?!",
  ui_story_5072_50721002_23_dialog_content = "Apakah sampan sudah hanyut mendekati pantai?",
  ui_story_5072_50721002_24_dialog_content = "Jumlah penonton juga semakin bertambah. Ini tidak baik...",
  ui_story_5072_50721002_25_dialog_content = "Tidak, ada dua pendekar pedang yang sedang bertarung!",
  ui_story_5072_50721002_26_dialog_content = "Yang berada dalam bayangan adalah Tuan Rumah Vilanor, yang lainnya adalah...",
  ui_story_5072_50721002_27_dialog_content = "Mercenary terkenal dari Umbraton dengan duri di seluruh tubuhnya, Pedang Sihir Arrie!",
  ui_story_5072_50721002_28_dialog_content = "Oh tidak, pakaianku... Penyamaranku terbongkar.",
  ui_story_5072_50721002_29_dialog_content = "Ya, perahu akan merapat sebentar lagi, memberikan banyak tubuh baru untuk saya kuasai!",
  ui_story_5072_50721002_30_dialog_content = "<color=#e8d9bb>Dug!</color>",
  ui_story_5072_50721002_31_dialog_content = "Terima kasih telah membiarkan saya...",
  ui_story_5072_50721002_32_dialog_content = "Tunggu... Aku lelah...",
  ui_story_5072_50721002_33_dialog_content = "Pasukan Vilanor berhasil kabur lagi... Saya sangat minta maaf...",
  ui_story_5072_50721101_1_dialog_content = "...",
  ui_story_5072_50721101_2_dialog_content = "...",
  ui_story_5072_50721101_3_dialog_content = "Tidak ada yang harus melihatku di sini.",
  ui_story_5072_50721101_4_dialog_content = "Fiuh, setidaknya untuk sementara aku tidak perlu bertarung...",
  ui_story_5072_50721101_5_dialog_content = "Astaga, tiba-tiba Pedang Ajaib ini terasa sangat berat.",
  ui_story_5072_50721101_6_dialog_content = "Apa yang kamu lakukan di sini, Arrie? Aku telah mencarimu.",
  ui_story_5072_50721101_7_dialog_content = "Oh hai...",
  ui_story_5072_50721101_8_dialog_content = "Maafkan saya karena tidak datang kepadamu.",
  ui_story_5072_50721101_9_dialog_content = "Nah, saya punya kabar baik untuk dibagikan.",
  ui_story_5072_50721101_10_dialog_content = "Markas besar telah setuju untuk membantu kami membawa Vilanor's Host dan menyimpan pedangnya.",
  ui_story_5072_50721101_11_dialog_content = "Jadi kita memiliki tujuan baru dan tujuan utama kita sekarang adalah...",
  ui_story_5072_50721101_12_dialog_content = "Um, maaf...",
  ui_story_5072_50721101_13_dialog_content = "Maaf? Ada apa, Arrie?",
  ui_story_5072_50721101_14_dialog_content = "Kurasa aku tidak bisa melanjutkan pekerjaan ini.",
  ui_story_5072_50721101_15_dialog_content = "...",
  ui_story_5072_50721101_16_dialog_content = "Seharusnya aku yang minta maaf karena terus bertele-tele sendirian.",
  ui_story_5072_50721101_17_dialog_content = "Saya mendengar orang-orang berbicara tentang dua pendekar pedang yang bertarung di sungai. Melihat penampilanmu sekarang...",
  ui_story_5072_50721101_18_dialog_content = "Apakah ada sesuatu yang salah saat kamu melawan Vilanor's Host?",
  ui_story_5072_50721101_19_dialog_content = "Jangan bilang beberapa pelaut tukang onar itu salah mengira kamu sebagai Tuan Rumah Vilanor?!",
  ui_story_5072_50721101_20_dialog_content = "Aku baik-baik saja meskipun begitu dan mendapatkan pandangan samping. Aku sudah terbiasa dengan itu.",
  ui_story_5072_50721101_21_dialog_content = "Aku ingin berhenti karena aku benar-benar menyadarinya sekarang...",
  ui_story_5072_50721101_22_dialog_content = "Aku tidak bisa mengalahkan Tuan Rumah Vilanor.",
  ui_story_5072_50721101_23_dialog_content = "Sebagai wakil, aku tidak bisa mengalahkannya.",
  ui_story_5072_50721101_24_dialog_content = "Proxy? Itu adalah hak yang diperuntukkan bagi pengrajin saja. Jangan berkelahi denganku untuk itu, Arrie.",
  ui_story_5072_50721101_25_dialog_content = "Apakah Tuan Rumah Vilanor menanamkan ide gila di kepalamu? Jangan dengarkan dia!",
  ui_story_5072_50721101_26_dialog_content = "Tidak, dia benar...",
  ui_story_5072_50721101_27_dialog_content = "Seperti dia, aku bukanlah pendekar pedang melainkan perantara, jadi aku tidak bisa memaksimalkan kekuatan pedangku.",
  ui_story_5072_50721101_28_dialog_content = "Sementara Pasukan Vilanor memiliki akses penuh ke pedangnya, aku menahan Pedang Ajaib ini.",
  ui_story_5072_50721101_29_dialog_content = "Itu omong kosong, Arrie.",
  ui_story_5072_50721101_30_dialog_content = "Pedangmu adalah kebalikan dari pedang jahat yang penuh dendam itu. Dia melindungimu.",
  ui_story_5072_50721101_31_dialog_content = "Pedangmu pasti akan sedih mendengarmu mengatakan itu.",
  ui_story_5072_50721101_32_dialog_content = "Tidak, niatku bukan untuk merendahkan Pedang Ajaib.",
  ui_story_5072_50721101_33_dialog_content = "Dia sangat merawatku dan tidak pernah memanggilku sebagai proxy.",
  ui_story_5072_50721101_34_dialog_content = "Tapi selalu aku yang menjadi orang yang bergantung.",
  ui_story_5072_50721101_35_dialog_content = "Pedang bisa tanpa saya, tetapi saya tidak bisa tanpa pedang itu.",
  ui_story_5072_50721101_36_dialog_content = "Ini adalah bukti kekuatan Pedang Ajaib bahwa saya bahkan bertahan untuk menjadi seorang tentara bayaran.",
  ui_story_5072_50721101_37_dialog_content = "Jika itu diambil dariku, aku hanya seorang gadis yang membosankan dan lemah yang tidak pandai dalam apapun.",
  ui_story_5072_50721101_38_dialog_content = "Ayo, Arrie. Itu bukanlah dirimu bagiku. Kau adalah tentara bayaran yang bisa diandalkan dan perkasa dengan caramu sendiri!",
  ui_story_5072_50721101_39_dialog_content = "Tapi jika aku tidak memiliki pedang, aku tidak akan memiliki nilai apa-apa untukmu.",
  ui_story_5072_50721101_40_dialog_content = "Seperti sekarang, tidak ada yang akan melihatku sebagai sosialita setelah merobek pakaian yang kamu berikan padaku.",
  ui_story_5072_50721101_41_dialog_content = "Saya hanya Arrie, seorang tentara bayaran Umbraton dengan duri di seluruh tubuhnya.",
  ui_story_5072_50721101_42_dialog_content = "Mungkin dengan pemegang yang lebih hebat, ia akan dengan mudah mengalahkan Vilanor.",
  ui_story_5072_50721101_43_dialog_content = "Tidak ada yang dirasuki oleh Vilanor lebih tangguh darimu, Arrie.",
  ui_story_5072_50721101_44_dialog_content = "Ini dapat mengubah pemegangnya sesuai keinginan, sehingga memiliki keunggulan yang menentukan dalam hal stamina.",
  ui_story_5072_50721101_45_dialog_content = "Tapi aku tidak bisa mengalahkannya. Aku bahkan merobek penyamaran yang sangat penting untuk misi ini. Itu adalah fakta.",
  ui_story_5072_50721101_46_dialog_content = "Mungkin kamu harus menyewa tentara bayaran yang lebih baik untuk menyelesaikan pekerjaan ini.",
  ui_story_5072_50721101_47_dialog_content = "Arrie...",
  ui_story_5072_50721101_48_dialog_content = "...",
  ui_story_5072_50721101_49_dialog_content = "Kau mau ke mana, Arrie?",
  ui_story_5072_50721101_50_dialog_content = "Entahwah...",
  ui_story_5072_50721101_51_dialog_content = "Apa kamu mau berhenti dari pekerjaan? Dan juga menyerah pada dirimu sendiri?",
  ui_story_5072_50721101_52_dialog_content = "Aku hanya tidak bisa melakukannya...",
  ui_story_5072_50721101_53_dialog_content = "...",
  ui_story_5072_50721101_54_dialog_content = "Aku akan menyerahkan keputusan akhir padamu...",
  ui_story_5072_50721101_55_dialog_content = "Tapi, sebelum kamu berhenti, bagaimana kalau aku bercerita?",
  ui_story_5072_50721101_56_dialog_content = "Kisah?",
  ui_story_5072_50721101_57_dialog_content = "Ya, satu yang baru saja aku dengar... tidak, baru saja teringat, tentang seorang pahlawan yang dikutuk oleh Eclipsite.",
  ui_story_5072_50721101_58_dialog_content = "Seorang pahlawan kuno dikutuk dengan penyakit abadi dalam pertempurannya melawan Eclipsites.",
  ui_story_5072_50721101_59_dialog_content = "Tidak hanya itu, setiap keturunan darinya yang mahir dalam memburu Eclipsite juga akan mati muda karena kutukan.",
  ui_story_5072_50721101_60_dialog_content = "Setiap orang biasa akan meninggalkan takdir heroik semacam itu karena ketakutan.",
  ui_story_5072_50721101_61_dialog_content = "Dan ingatkan keluarganya untuk menjauh dari latihan atau perang apa pun yang menentang Eclipsites.",
  ui_story_5072_50721101_62_dialog_content = "Namun, pahlawan memilih untuk menggunakan tubuh terkutuknya sebagai komponen dasar.",
  ui_story_5072_50721101_63_dialog_content = "Dan tempa pedang di bawah berkat bulan.",
  ui_story_5072_50721101_64_dialog_content = "Sejak saat itu, pedang ini telah melindungi keturunannya yang terampil dalam berkelahi dan melawan kutukan Eclipsites.",
  ui_story_5072_50721101_65_dialog_content = "Semua dari mereka bertarung dengan berani...",
  ui_story_5072_50721102_1_dialog_content = "Itulah ceritanya.",
  ui_story_5072_50721102_2_dialog_content = "Namun, bentrokan antara pewaris pahlawan dan Eclipsite tidak akan pernah berakhir.",
  ui_story_5072_50721102_3_dialog_content = "Semakin hebat seorang prajurit, semakin besar perlindungan yang harus diberikan pedang. Itulah tujuan pedang.",
  ui_story_5072_50721102_4_dialog_content = "Bagi saya, kamu bukanlah orang yang tidak berarti, Arrie. Aku... Pedang Ajaib akan melindungimu...",
  ui_story_5072_50721102_5_dialog_content = "Karena aku mengakui betapa hebatnya kamu.",
  ui_story_5072_50721102_6_dialog_content = "Aku sangat berterima kasih untuk itu dan selalu begitu.",
  ui_story_5072_50721102_7_dialog_content = "Tapi, apakah aku pantas untuk itu?",
  ui_story_5072_50721102_8_dialog_content = "Tentu saja kamu. Aku tahu aku hanya sebuah pedang.",
  ui_story_5072_50721102_9_dialog_content = "Meskipun memiliki sejarah kuno dan mengembangkan kesadaran, pada dasarnya itulah diri saya.",
  ui_story_5072_50721102_10_dialog_content = "Kamu yang menentukan nasibku dan siapa yang akan kuhantam. Kamu belajar mengendalikan kekuatanku.",
  ui_story_5072_50721102_11_dialog_content = "Semangatmu tidak pernah luntur meski efek samping yang aku berikan padamu.",
  ui_story_5072_50721102_12_dialog_content = "Justru sebaliknya, kamu lah yang telah mempengaruhi saya, menunjukkan arah yang benar untuk duri-duri tersebut.",
  ui_story_5072_50721102_13_dialog_content = "Itu benar-benar berbeda dari Vilanor yang selalu mengambil keuntungan dari orang lain.",
  ui_story_5072_50721102_14_dialog_content = "Nah, sebagai pemegang, kita semua dilindungi oleh kekuatan besar dari pedang masing-masing...",
  ui_story_5072_50721102_15_dialog_content = "Kau salah, Arrie.",
  ui_story_5072_50721102_16_dialog_content = "Apakah kamu benar-benar berpikir bahwa Vilanor melindungi pemegangnya?",
  ui_story_5072_50721102_17_dialog_content = "Hah?",
  ui_story_5072_50721102_18_dialog_content = "Tampaknya ia melindungi pemegangnya hanya karena tidak ingin kalah. Ia tidak peduli siapa yang memegangnya.",
  ui_story_5072_50721102_19_dialog_content = "Itu adalah sifat dari Vilanor. Itu akan menerima siapa saja.",
  ui_story_5072_50721102_20_dialog_content = "Tapi kamu, Arrie, adalah satu-satunya majikan untukku dan Pedang Sihir!",
  ui_story_5072_50721102_21_dialog_content = "...",
  ui_story_5072_50721102_22_dialog_content = "Aku adalah tuan dari Pedang Ajaib...",
  ui_story_5072_50721102_23_dialog_content = "Tunggu, apakah itu berarti cerita yang baru saja kamu ceritakan adalah asal-usul pedangku?!",
  ui_story_5072_50721102_24_dialog_content = "Kamu sudah mengerti... Seperti yang pernah aku katakan sebelumnya, aku hanya tahu tentang pedang khusus ini.",
  ui_story_5072_50721102_25_dialog_content = "Pedang ini sangat tua, jadi saya hanya bisa menyatukan ingatannya melalui potongan-potongan.",
  ui_story_5072_50721102_26_dialog_content = "Detailnya mungkin tidak sepenuhnya benar, jadi jangan salahkan saya.",
  ui_story_5072_50721102_27_dialog_content = "Tidak.",
  ui_story_5072_50721102_28_dialog_content = "Ini adalah yang paling banyak yang pernah saya pelajari tentang kutukan itu.",
  ui_story_5072_50721102_29_dialog_content = "Terima kasih.",
  ui_story_5072_50721102_30_dialog_content = "Saya rasa saya tahu apa yang harus saya lakukan.",
  ui_story_5072_50721102_31_dialog_content = "Aku akan menemui Miss Armilla dan menyelesaikan pekerjaan!",
  ui_story_5072_50721102_32_dialog_content = "Nona Armilla...",
  ui_story_5072_50721102_33_dialog_content = "Arrie? Ayo duduk bersamaku. Pelayan, berikan aku dua keranjang lagi bakpao sup dengan tambahan cabai.",
  ui_story_5072_50721102_34_dialog_content = "Tunggu sebentar!",
  ui_story_5072_50721102_35_dialog_content = "Uh, apakah kamu bertemu dengan seorang informan di sini?",
  ui_story_5072_50721102_36_dialog_content = "Tidak. Piring dan peralatan makan itu untuk kamu.",
  ui_story_5072_50721102_37_dialog_content = "Apa?",
  ui_story_5072_50721102_38_dialog_content = "Kamu hanya kelelahan saat itu, setelah semua. Aku yakin Pedang Sihir milikmu akan membuat pikiranmu jernih.",
  ui_story_5072_50721102_39_dialog_content = "Kamu tahu tentang pedang ajaibku?",
  ui_story_5072_50721102_40_dialog_content = "Tidak benar-benar, tapi aku tahu bagaimana kalian berdua bertarung.",
  ui_story_5072_50721102_41_dialog_content = "Chemistry yang kamu miliki bukanlah sesuatu yang bisa disentuh oleh Tuan Rumah Vilanor.",
  ui_story_5072_50721102_42_dialog_content = "Maaf karena tidak memikirkan apa yang kamu katakan sebelumnya.",
  ui_story_5072_50721102_43_dialog_content = "Bukan hanya aku, bagaimanapun.",
  ui_story_5072_50721102_44_dialog_content = "Semua orang tak berdosa di geladak yang kamu selamatkan sangat menghargai kamu.",
  ui_story_5072_50721102_45_dialog_content = "Mereka semua menantikan pahlawan yang akan membunuh Pasukan Vilanor jahat itu dengan pedang ajaibnya.",
  ui_story_5072_50721102_46_dialog_content = "Nah, jika tidak terlalu terlambat, bisakah saya masih menyelesaikan pekerjaan ini?",
  ui_story_5072_50721102_47_dialog_content = "Bukankah dari awal saya sudah bilang bahwa pekerjaan itu hanya milikmu dan milikmu saja?",
  ui_story_5072_50721102_48_dialog_content = "Mari makan selagi makanannya masih panas... Ngomong-ngomong, ada ide bagaimana cara mengalahkan Vilanor's Host?",
  ui_story_5072_50721102_49_dialog_content = "Sebenarnya, aku punya kesempatan untuk mengalahkan Vilanor dengan bantuan Magic Sword.",
  ui_story_5072_50721102_50_dialog_content = "Oh?",
  ui_story_5072_50721102_51_dialog_content = "Kami berada di sebuah kolek dan saya berpikir jika saya bisa menjatuhkannya ke dalam air, itu tidak akan bisa memiliki siapa pun lagi.",
  ui_story_5072_50721102_52_dialog_content = "Tapi saat itu aku terlalu lelah dan penakut, jadi aku tidak bisa memberikan pukulan terakhir.",
  ui_story_5072_50721102_53_dialog_content = "Jika tidak ada orang lain di sekitar dan, daripada berhadapan langsung dengan Vilanor's Host, aku melucuti pedangnya...",
  ui_story_5072_50721102_54_dialog_content = "Mungkin itu cara untuk menundukkannya.",
  ui_story_5072_50721102_55_dialog_content = "Itulah Pedang Sihir Arrie yang aku kenal. Hanya kamu yang bisa membuat rencana seperti itu.",
  ui_story_5072_50721102_56_dialog_content = "Tapi Vilanor mungkin sudah mengantisipasi itu sekarang, jadi mungkin tidak akan berhasil...",
  ui_story_5072_50721102_57_dialog_content = "Tidak apa-apa. Kita akan mencari cara lain untuk mencapai tujuan itu.",
  ui_story_5072_50721102_58_dialog_content = "Bagaimanapun, itu baru saja mendapatkan kesadaran belum lama ini.",
  ui_story_5072_50721102_59_dialog_content = "Masih banyak yang harus dipelajari tentang trik dan strategi.",
  ui_story_5072_50721102_60_dialog_content = "Istirahatlah sekarang, Arrie, dan ganti bajumu sementara aku menyiapkan segalanya.",
  ui_story_5072_50721102_61_dialog_content = "Mari luncurkan serangan terakhir pada Vilanor malam ini!",
  ui_story_5072_50721201_1_dialog_content = "Maaf, Arrie, karena datang di sini terlambat.",
  ui_story_5072_50721201_2_dialog_content = "Memakan waktu lebih lama dari yang saya kira untuk memberi tahu orang-orang yang dikirim oleh markas tentang rencana saya.",
  ui_story_5072_50721201_3_dialog_content = "Tapi semuanya sudah siap sekarang. Apakah kamu siap untuk pertarungan final dengan Tuan Rumah Vilanor?",
  ui_story_5072_50721201_4_dialog_content = "Aku siap. Tapi ke mana tujuanku?",
  ui_story_5072_50721201_5_dialog_content = "Benteng.",
  ui_story_5072_50721201_6_dialog_content = "Benteng... Aku paham.",
  ui_story_5072_50721201_7_dialog_content = "Jatuhkan dari benteng dan tidak akan ada siapa pun di sekitar untuk dirasuki.",
  ui_story_5072_50721201_8_dialog_content = "Itu rencananya. Tapi tidak akan mudah untuk memancing Pendekar Pedang ke sana.",
  ui_story_5072_50721201_9_dialog_content = "Kami melihat Tuan Rumah Vilanor, Nona Armilla.",
  ui_story_5072_50721201_10_dialog_content = "Oke. Kita harus bergegas.",
  ui_story_5072_50721201_11_dialog_content = "...",
  ui_story_5072_50721201_12_dialog_content = "Ah, saya melihat banyak orang.",
  ui_story_5072_50721201_13_dialog_content = "Tapi kau pikir hanya ini yang diperlukan untuk menundukkanku?",
  ui_story_5072_50721201_14_dialog_content = "Kamu sedang melawanku!",
  ui_story_5072_50721201_15_dialog_content = "Hei, bukankah kamu proxy itu?",
  ui_story_5072_50721201_16_dialog_content = "Apakah aku telah menyentuh titik sensitifmu? Apakah itu sebabnya kamu terus menggangguku?",
  ui_story_5072_50721201_17_dialog_content = "Maka akan kubuktikan betapa rendahnya dirimu dibandingkan denganku!",
  ui_story_5072_50721201_18_dialog_content = "<color=#e8d9bb>Dentang! Dentang!</color>",
  ui_story_5072_50721201_19_dialog_content = "Kamu masih lemah seperti biasanya. Kamu tidak bisa bertahan dari serangan-seranganku tanpa pedang ajaibmu.",
  ui_story_5072_50721201_20_dialog_content = "Saya berada dalam keadaan yang sangat tidak menguntungkan...",
  ui_story_5072_50721201_21_dialog_content = "Terus mundur. Aku ingin melihat sejauh mana kamu bisa mundur.",
  ui_story_5072_50721201_22_dialog_content = "Itu jalan buntu. Pernahkah kamu mempertimbangkan betapa buruk posisi yang sedang kamu hadapi sekarang?",
  ui_story_5072_50721201_23_dialog_content = "Kamu benar-benar berpikir ini jalan buntu? Ini lebih mudah dari yang kubayangkan, Tuan Vilanor... Tidak, aku seharusnya memanggilmu Vilanor.",
  ui_story_5072_50721201_24_dialog_content = "Cepat, Miss Arrie telah memancing Tuan Rumah Vilanor ke atas sana. Tutup semua pintu keluar sekarang!",
  ui_story_5072_50721201_25_dialog_content = "<color=#e8d9bb>Pranggg... Wham!</color>",
  ui_story_5072_50721201_26_dialog_content = "Apa…?!",
  ui_story_5072_50721201_27_dialog_content = "Inilah tempat berakhirnya pemerintahan teror Anda.",
  ui_story_5072_50721201_28_dialog_content = "Aku tidak akan melawanmu di sini. Kamu tidak bisa menjebakku di sini! Terkutuklah mereka semua!",
  ui_story_5072_50721201_29_dialog_content = "Jangan khawatir tentang mereka. Sudah kubilang, kamu yang akan melawanku!",
  ui_story_5072_50721301_1_dialog_content = "Baiklah, saya rasa kita berdua tidak bisa pergi kemana-mana.",
  ui_story_5072_50721301_2_dialog_content = "Jadi kamu pikir ini adalah akhirku? Bagiku, ini tampak seperti tempat peristirahatan terakhirmu!",
  ui_story_5072_50721301_3_dialog_content = "Rasakan ini!",
  ui_story_5072_50721301_4_dialog_content = "<color=#e8d9bb>Wuush!</color>",
  ui_story_5072_50721301_5_dialog_content = "Itu tidak mendarat?!",
  ui_story_5072_50721301_6_dialog_content = "Apakah kamu pikir kamu memiliki ruang untuk lari di tempat yang sempit ini?",
  ui_story_5072_50721301_7_dialog_content = "<color=#e8d9bb>Wuush!</color>",
  ui_story_5072_50721301_8_dialog_content = "...",
  ui_story_5072_50721301_9_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5072_50721301_10_dialog_content = "Tidak mungkin!",
  ui_story_5072_50721301_11_dialog_content = "Mustahil! Anda hanya seorang wakil, bagaimana Anda bisa bekerja dengan baik dengan Pedang Ajaib!",
  ui_story_5072_50721301_12_dialog_content = "Proxy? Tidak, pedang ini dan saya adalah mitra!",
  ui_story_5072_50721301_13_dialog_content = "Aku membimbingnya untuk menyerang, dan ia membimbingku menuju takdirku!",
  ui_story_5072_50721301_14_dialog_content = "<color=#e8d9bb>Wuush... Klang!</color>",
  ui_story_5072_50721301_15_dialog_content = "Bagaimana mungkin kamu bisa memblokir itu?!",
  ui_story_5072_50721301_16_dialog_content = "Giliran saya!",
  ui_story_5072_50721301_17_dialog_content = "<color=#e8d9bb>Wuush!</color>",
  ui_story_5072_50721301_18_dialog_content = "Oh, tidak!",
  ui_story_5072_50721301_19_dialog_content = "Jadi, ini rencanamu, begitu.",
  ui_story_5072_50721301_20_dialog_content = "Jatuhkan aku dari benteng dan tidak ada orang yang bisa kukuasai.",
  ui_story_5072_50721301_21_dialog_content = "...",
  ui_story_5072_50721301_22_dialog_content = "Heh... Hahahaha!",
  ui_story_5072_50721301_23_dialog_content = "Apanya yang lucu?",
  ui_story_5072_50721301_24_dialog_content = "Kamu mengabaikan satu detail penting.",
  ui_story_5072_50721301_25_dialog_content = "Saya memiliki boneka yang bisa digantikan dengan sempurna!",
  ui_story_5072_50721301_26_dialog_content = "Bagaimana kamu akan bertarung jika aku hanya menggunakan dia sebagai tameng daging? Apakah kamu akan membunuh seorang pria yang tidak bersalah dengan pedangmu?",
  ui_story_5072_50721301_27_dialog_content = "Hmm, Armilla memang jenius bisa melihat ini datang.",
  ui_story_5072_50721301_28_dialog_content = "Yah. Ini dia kaitnya!",
  ui_story_5072_50721301_29_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_5072_50721301_30_dialog_content = "Apa ini?!",
  ui_story_5072_50721301_31_dialog_content = "Kait dan rantai pintle, sehingga kamu tidak bisa lagi mengeksploitasi tubuh manusia yang terikat.",
  ui_story_5072_50721301_32_dialog_content = "Tidak... Lepaskan aku, sekarang!",
  ui_story_5072_50721301_33_dialog_content = "Berhenti menggeliat. Pengrajin terbaik di Longzhou yang membuat ini. Semakin kamu berjuang, semakin ketat ini menjadi.",
  ui_story_5072_50721301_34_dialog_content = "Pedang Ajaib lahir di bawah berkat bulan.",
  ui_story_5072_50721301_35_dialog_content = "Mohon berkatilah lagi untukku agar dapat menundukkan Vilanor ini!",
  ui_story_5072_50721302_1_dialog_content = "Ini adalah akhirnya!",
  ui_story_5072_50721302_2_dialog_content = "<color=#e8d9bb>Wuush!</color>",
  ui_story_5072_50721302_3_dialog_content = "Aaaaaaaargh!!",
  ui_story_5072_50721302_4_dialog_content = "<color=#e8d9bb>Dug!</color>",
  ui_story_5072_50721302_5_dialog_content = "Lady dari Longzhou menang!",
  ui_story_5072_50721302_6_dialog_content = "Cepat, naik dan bebaskan korban pedang terkutuk!",
  ui_story_5072_50721302_7_dialog_content = "Selamat, Nyonya. Misi telah selesai.",
  ui_story_5072_50721302_8_dialog_content = "Dalam hal itu, saya bukan lagi wanita dari Longzhou.",
  ui_story_5072_50721302_9_dialog_content = "Apa yang kamu katakan? Identitas dan citra itu sekarang sudah tak terhapuskan di pikiran semua orang.",
  ui_story_5072_50721302_10_dialog_content = "Ini telah menjadi bagian darimu, sama seperti Pedang Ajaib Arrie.",
  ui_story_5072_50721302_11_dialog_content = "Bagaimana keadaan pria yang kerasukan itu?",
  ui_story_5072_50721302_12_dialog_content = "Dia baik-baik saja. Kamu menghindari bagian vital dalam semua seranganmu. Sangat baik dari kamu.",
  ui_story_5072_50721302_13_dialog_content = "Masalah terbesar sekarang adalah...",
  ui_story_5072_50721302_14_dialog_content = "Aku akan menanganinya. Dengan sarung tangan yang kamu berikan padaku, Miss Armilla, seharusnya tidak menjadi masalah.",
  ui_story_5072_50721302_15_dialog_content = "Tetapi sarung tangan ini tidak akan menekan semua kekuatannya, jadi segera lepaskan begitu Anda merasa ada yang tidak beres, oke?",
  ui_story_5072_50721302_16_dialog_content = "Ya. Akan kuingat itu...",
  ui_story_5072_50721302_17_dialog_content = "...",
  ui_story_5072_50721302_18_dialog_content = "(Benci, benci, benci...)",
  ui_story_5072_50721302_19_dialog_content = "(Bunuh, bunuh, bunuh...)",
  ui_story_5072_50721302_20_dialog_content = "<size=45>(Aku mencari... balas dendam...!)</size>",
  ui_story_5072_50721302_21_dialog_content = "Hei, kau baik-baik saja, Arrie?!",
  ui_story_5072_50721302_22_dialog_content = "Ugh...",
  ui_story_5072_50721302_23_dialog_content = "Tidak, harus mengambil pedang terkutuk itu sebelum Arrie terpengaruh!",
  ui_story_5072_50721302_24_dialog_content = "...",
  ui_story_5072_50721302_25_dialog_content = "Agh!",
  ui_story_5072_50721302_26_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5072_50721302_27_dialog_content = "Vilanor... Dia terbang sendiri!",
  ui_story_5072_50721302_28_dialog_content = "...",
  ui_story_5072_50721302_29_dialog_content = "<color=#e8d9bb>Wuush!</color>",
  ui_story_5072_50721302_30_dialog_content = "Bell Barrage, serang!",
  ui_story_5072_50721302_31_dialog_content = "<color=#e8d9bb>Wuush!</color>",
  ui_story_5072_50721302_32_dialog_content = "Ini harus melakukannya.",
  ui_story_5072_50721302_33_dialog_content = "Apakah kamu baik-baik saja, Arrie?",
  ui_story_5072_50721401_1_dialog_content = "Bicara padaku, Arrie!",
  ui_story_5072_50721401_2_dialog_content = "Aku baik-baik saja. Namun...",
  ui_story_5072_50721401_3_dialog_content = "Karena aku, pedang itu lolos sekali lagi.",
  ui_story_5072_50721401_4_dialog_content = "Jika itu memiliki seseorang lain...",
  ui_story_5072_50721401_5_dialog_content = "Kita harus mulai dari awal lagi.",
  ui_story_5072_50721401_6_dialog_content = "Tidak apa-apa, kami punya waktu.",
  ui_story_5072_50721401_7_dialog_content = "Jam malam Guild Umbraton sudah diberlakukan sekarang, jadi tidak ada orang di jalanan yang menjadi boneka Vilanor.",
  ui_story_5072_50721401_8_dialog_content = "Juga, dalam keadaan saat ini, mungkin dia pergi karena insting dan tidak memiliki keinginan untuk memiliki siapa pun.",
  ui_story_5072_50721401_9_dialog_content = "Jadi, kita harus bergerak sekarang dan melacaknya.",
  ui_story_5072_50721401_10_dialog_content = "Tapi Twin Pavilions Bay sangat luas... Di mana kita harus mulai?",
  ui_story_5072_50721401_11_dialog_content = "Jika kita tidak bisa menemukannya sebelum fajar...",
  ui_story_5072_50721401_12_dialog_content = "Tenang, aku sudah menandainya.",
  ui_story_5072_50721401_13_dialog_content = "Menandainya?",
  ui_story_5072_50721401_14_dialog_content = "Iya, tapi kali ini.",
  ui_story_5072_50721401_15_dialog_content = "<color=#e8d9bb>Ding, ding...</color>",
  ui_story_5072_50721401_16_dialog_content = "Lonceng?",
  ui_story_5072_50721401_17_dialog_content = "Iya. Aku mengikat salah satu sebelum itu terbang menjauh.",
  ui_story_5072_50721401_18_dialog_content = "Kota ini sangat hening sekarang, jadi kita bisa mengikuti suara gemerincing menuju pedang.",
  ui_story_5072_50721401_19_dialog_content = "Begitu ya. Ayo pergi kalau begitu!",
  ui_story_5072_50721401_20_dialog_content = "Ini mendesak. Haruskah kita berpencar?",
  ui_story_5072_50721401_21_dialog_content = "Tidak, ini akan menjadi masalah besar jika salah satu dari kita kerasukan.",
  ui_story_5072_50721401_22_dialog_content = "Bersama-sama, kita bisa saling menjaga, bahkan ketika dilanda kebencian pedang.",
  ui_story_5072_50721401_23_dialog_content = "Saya mengerti. Oh, maaf telah meremehkan emosi mentah yang dipancarkannya. Saya tidak berharap itu akan begitu intens.",
  ui_story_5072_50721401_24_dialog_content = "Bukan salahmu, Arrie. Aku sendiri sedikit ceroboh.",
  ui_story_5072_50721401_25_dialog_content = "Wajahmu tampak menderita saat kamu memegang pedang. Apa yang kamu rasakan?",
  ui_story_5072_50721401_26_dialog_content = "Cemoohan yang luar biasa, rasa sakit, panik...",
  ui_story_5072_50721401_27_dialog_content = "Sepertinya ia sangat membenci dunia dan penderitaannya sendiri hingga ke ekstrem.",
  ui_story_5072_50721401_28_dialog_content = "Itulah sebabnya ia terus merasuki orang dan mencari balas dendam seolah-olah untuk mengakhiri kebencian yang tak berbatas...",
  ui_story_5072_50721401_29_dialog_content = "Markas besar telah mengetahui bahwa pemilik dapur adalah seorang pedagang gelap yang mendapatkan pedang dari bajak laut.",
  ui_story_5072_50721401_30_dialog_content = "Namun, trauma diculik dari rumah melahirkan kebencian dan merusak kekuatan kuno pedang.",
  ui_story_5072_50721401_31_dialog_content = "Sampai akhirnya ia naik pangkat menjadi pedang jahat dan mengutuk barang-barang antik di sekitarnya serta para pelaut yang mengangkutnya.",
  ui_story_5072_50721401_32_dialog_content = "Guild Red Shell, sang kolektor, dan pemegang pedang, semuanya terlibat dalam jalur balas dendamnya.",
  ui_story_5072_50721401_X32_dialog_content = "Jika penyelesaian dan keserakahan tidak berakhir, dendam mungkin juga tidak akan pernah berakhir.",
  ui_story_5072_50721401_33_dialog_content = "Jadi, apa yang kita lakukan sekarang bukan menguncinya?",
  ui_story_5072_50721401_34_dialog_content = "Tidak. Kita harus menghilangkan emosi negatifnya. Cara terbaik untuk melakukan itu adalah...",
  ui_story_5072_50721401_35_dialog_content = "Bawa itu pulang ke rumah.",
  ui_story_5072_50721401_36_dialog_content = "<color=#e8d9bb>Ding... Ding...</color>",
  ui_story_5072_50721401_37_dialog_content = "Jelas seperti suara lonceng... Ayo, ke arah itu!",
  ui_story_5072_50721601_1_dialog_content = "Suara itu datang dari perahu ini.",
  ui_story_5072_50721601_2_dialog_content = "Kita masuk tanpa bisa melihat?",
  ui_story_5072_50721601_3_dialog_content = "Ya. Sepertinya aku tahu di mana itu akan berada.",
  ui_story_5072_50721601_4_dialog_content = "Apakah kamu menyadari bahwa kapal ini terlihat berbeda dari yang lain yang kita lihat di luar?",
  ui_story_5072_50721601_5_dialog_content = "Ini tampak seperti kapal lainnya di Sungai Emas, tetapi geladaknya sebenarnya...",
  ui_story_5072_50721601_6_dialog_content = "Khas dari kapal pesiar Lin.",
  ui_story_5072_50721601_7_dialog_content = "Vilanor menciptakan ilusi kapal pesiar di atas kapal pengangkut Gold River.",
  ui_story_5072_50721601_8_dialog_content = "Ini jenis kapal yang ingin diambil dan kembali ke rumah.",
  ui_story_5072_50721601_9_dialog_content = "Kami berada di ruang kargo utama.",
  ui_story_5072_50721601_10_dialog_content = "Saya dengar pemilik kapal ini bekerja untuk bajak laut dan penjahat, itulah sebabnya dia membutuhkan ruang kargo yang besar...",
  ui_story_5072_50721601_11_dialog_content = "Mereka juga memeras uang perlindungan dari kapal-kapal di sekitarnya.",
  ui_story_5072_50721601_12_dialog_content = "Itu menjelaskannya. Semua keuntungan dan keserakahan yang membengkak itu telah mengutuk pedang.",
  ui_story_5072_50721601_13_dialog_content = "Saya bertanya-tanya berapa banyak peninggalan Longzhou yang berakhir di Astra seperti ini dan tidak pernah melihat rumah lagi.",
  ui_story_5072_50721601_14_dialog_content = "Jadi, Vilanor datang ke sini dengan harapan bisa kembali ke Longzhou dengan kapal ini...",
  ui_story_5072_50721601_15_dialog_content = "Benar. Kembali ke rumahnya dan menemukan kembali tujuannya.",
  ui_story_5072_50721601_16_dialog_content = "Magic Sword? Sudah lama aku tidak mendengar kabar darimu.",
  ui_story_5072_50721601_17_dialog_content = "Apa lagi yang bisa kamu rasakan dari Vilanor?",
  ui_story_5072_50721601_18_dialog_content = "Harus kuakui, benda ini telah sepenuhnya dirusak oleh keserakahan sehingga sulit bagiku untuk mendapatkan apa pun yang lain.",
  ui_story_5072_50721601_19_dialog_content = "Tapi kerinduan akan rumah dan mencoba menemukan tujuannya ada...",
  ui_story_5072_50721601_20_dialog_content = "Terus berharap untuk kembali hanya untuk dipindahkan dan dijadikan koleksi berulang kali, hingga akhirnya menjadi mesin pembunuh...",
  ui_story_5072_50721601_21_dialog_content = "Rasa sakit, penderitaan, penyerahan diri.",
  ui_story_5072_50721601_22_dialog_content = "Jika saya mengalami penderitaan yang sama, mungkin itu juga bisa membuat saya jahat.",
  ui_story_5072_50721601_23_dialog_content = "Tidak mungkin!",
  ui_story_5072_50721601_24_dialog_content = "Tentu saja tidak, karena aku memiliki pemilik terbaik di dunia!",
  ui_story_5072_50721601_25_dialog_content = "…!",
  ui_story_5072_50721601_26_dialog_content = "Hati-hati, Arrie, aku rasa dia melihat kita.",
  ui_story_5072_50721601_27_dialog_content = "Dan itu melihat kita sebagai musuh.",
  ui_story_5072_50721601_28_dialog_content = "Ada cara untuk menenangkannya?",
  ui_story_5072_50721601_29_dialog_content = "Meskipun ada, kita tetap harus menundukkan mereka terlebih dahulu. Ayo lakukan ini, Arrie.",
  ui_story_5072_50721601_30_dialog_content = "Tentu!",
  ui_story_5072_50721602_1_dialog_content = "Sudah berakhir?",
  ui_story_5072_50721602_2_dialog_content = "Ia tidak bisa menyerang kita dalam waktu dekat.",
  ui_story_5072_50721602_3_dialog_content = "Aku membawa kotak pedang bersamaku jadi kita tidak perlu menyentuhnya...",
  ui_story_5072_50721602_4_dialog_content = "Tidak apa-apa, aku bisa menanganinya.",
  ui_story_5072_50721602_5_dialog_content = "Tunggu, kamu tidak menggunakan tangan telanjang, bukan...",
  ui_story_5072_50721602_6_dialog_content = "...",
  ui_story_5072_50721602_7_dialog_content = "...",
  ui_story_5072_50721602_8_dialog_content = "Huff... Puff...",
  ui_story_5072_50721602_9_dialog_content = "Tidak apa-apa. Tidak apa-apa...",
  ui_story_5072_50721602_10_dialog_content = "Kami di sini untuk menyelamatkanmu.",
  ui_story_5072_50721602_11_dialog_content = "Saya senang bahwa kamu bisa pulang setelah perjalanan yang begitu panjang.",
  ui_story_5072_50721602_12_dialog_content = "Ini keajaiban.",
  ui_story_5072_50721602_13_dialog_content = "Vilanor mulai tenang.",
  ui_story_5072_50721602_14_dialog_content = "Kurasa pola pikir pemegang memang bisa mempengaruhi pedang... Bahkan perangkat pun tidak bisa melakukan itu.",
  ui_story_5072_50721602_15_dialog_content = "Tolong ambil pedang ini.",
  ui_story_5072_50721602_16_dialog_content = "Pastikan itu kembali ke tempat asalnya.",
  ui_story_5072_50721602_17_dialog_content = "Siap.",
  ui_story_5072_50721602_18_dialog_content = "Oh...",
  ui_story_5072_50721602_19_dialog_content = "Dia tidak ingin meninggalkanmu...",
  ui_story_5072_50721602_20_dialog_content = "Karena belum pernah ada pemilik yang benar-benar peduli sebanyak kamu.",
  ui_story_5072_50721602_21_dialog_content = "Terima kasih atas tawarannya, tetapi saya tidak bisa menjadi pemilikmu karena saya sudah memiliki pedang sendiri.",
  ui_story_5072_50721602_22_dialog_content = "Belum lagi kamu masih memiliki tujuan yang harus dicari?",
  ui_story_5072_50721602_23_dialog_content = "Semoga kamu menemukan seseorang yang benar-benar menghargai kamu di kampung halamanmu...",
  ui_story_5072_50721602_24_dialog_content = "<color=#e8d9bb>Dug!</color>",
  ui_story_5072_50721602_25_dialog_content = "Kita akan menyebut ini sebagai perpisahan terakhir.",
  ui_story_5072_50721602_26_dialog_content = "Saya akan mengatur kapal untuk membawanya kembali ke Longzhou secepat mungkin.",
  ui_story_5072_50721602_27_dialog_content = "Sebagai gajimu...",
  ui_story_5072_50721602_28_dialog_content = "Itu tidak penting sekarang. Kamu harus segera melanjutkan rencanamu untuk pedang ini.",
  ui_story_5072_50721602_29_dialog_content = "Ini dalam potongan-potongan, tetapi saya mendapatkan gambaran yang cukup baik tentang masa lalu Pedang Ajaib.",
  ui_story_5072_50721602_30_dialog_content = "Melawan \"kutukan\" bukanlah masalah bagi saya sekarang, selama saya memiliki pedang ini dengan saya.",
  ui_story_5072_50721602_31_dialog_content = "Aku berhutang itu padamu, Nona Armilla.",
  ui_story_5072_50721602_32_dialog_content = "Tapi saya tidak melakukan apa-apa. Namun, jangan ragu untuk menemui saya kapan saja untuk informasi terbaru tentang Longzhou.",
  ui_story_5072_50721602_33_dialog_content = "Tetap temui saya, ketika Anda mencari gadget atau pakaian khas Longzhou juga.",
  ui_story_5072_50721602_34_dialog_content = "Aku paham.",
  ui_story_5072_50721602_35_dialog_content = "Sampai jumpa di lain waktu!",
  ui_story_5072_50721602_36_dialog_content = "Sampai jumpa.",
  ui_story_5072_50721602_37_dialog_content = "Kamu hebat, Magic Sword.",
  ui_story_5072_50721602_38_dialog_content = "Jika pedang itu memiliki keinginan, kamu pasti juga punya, 'kan?",
  ui_story_5072_50721602_39_dialog_content = "Ada tempat yang ingin kamu kunjungi? Haruskah saya membawa kamu kembali ke tempat orang tua saya menemukanmu?",
  ui_story_5072_50721602_40_dialog_content = "Aku menyadari kamu agak ragu saat menyerahkan pedang itu.",
  ui_story_5072_50721602_41_dialog_content = "Apakah pikiran untuk menggantiku pernah terlintas di benakmu?",
  ui_story_5072_50721602_42_dialog_content = "Apa? Tidak, tidak pernah! Bukan itu yang kupikirkan!",
  ui_story_5072_50721602_43_dialog_content = "Aku tahu, aku tahu... Hanya menggodamu, Arrie.",
  ui_story_5072_50721602_44_dialog_content = "Setiap orang lahir di suatu tempat dan akan mengunjungi banyak tempat penting dalam hidupnya.",
  ui_story_5072_50721602_45_dialog_content = "Tapi untuk saat ini, tinggal bersamamu adalah... uh, satu-satunya keinginan pedang... eh, keinginanku.",
  ui_story_5072_50721602_46_dialog_content = "Benarkah itu? Apa kamu yakin?",
  ui_story_5072_50721602_47_dialog_content = "Tentu saja. Sebagai pemilik saya, saya harap Anda akan lebih percaya diri.",
  ui_story_5072_50721602_48_dialog_content = "Takdir telah menentukan bahwa kamu harus menderita malapetaka yang kamu alami... Itu tak bisa diubah.",
  ui_story_5072_50721602_49_dialog_content = "Fakta bahwa saya dilahirkan untuk melindungimu juga tidak bisa diubah.",
  ui_story_5072_50721602_50_dialog_content = "Aku akan merasa sangat sengsara jika aku tidak bisa bersamamu dan berbagi bebanmu.",
  ui_story_5072_50721602_51_dialog_content = "Tolong izinkan aku tinggal agar aku tidak menjadi jahat dan penuh dendam!",
  ui_story_5072_50721602_52_dialog_content = "Oke, oke. Izinkan aku berterima kasih sebelumnya atas semua bantuanmu di masa depan!",
  ui_story_5072_50721602_53_dialog_content = "Sudah pagi.",
  ui_story_5072_50721602_54_dialog_content = "Ini adalah hari yang sempurna untuk seorang wanita pergi berbelanja... Tunggu, saya bukan lagi seorang sosialita.",
  ui_story_5072_50721602_X54_dialog_content = "Sebagai Pendekar Pedang Ajaib... atau hanya sebagai diriku sendiri.",
  ui_story_5072_50721602_55_dialog_content = "Aku memiliki masa depan di depanku... dan juga Pedang Ajaib.",
  ui_story_5072_50721602_56_dialog_content = "Hei, saatnya menyelesaikan ceritamu, tukang ramal.",
  ui_story_5072_50721602_57_dialog_content = "Anda tidak perlu mengatakannya lagi.",
  ui_story_5072_50721602_58_dialog_content = "Tapi di mana sih orang yang kesal yang aku baca ramalannya? Aku tidak melihatnya hari ini.",
  ui_story_5072_50721602_59_dialog_content = "Nah, inilah yang terjadi...",
  ui_story_5072_50721602_60_dialog_content = "Keuntungan kecil yang dia dapatkan berasal dari berjualan barang antik di pasar gelap.",
  ui_story_5072_50721602_X60_dialog_content = "Markas besar sedang menyelidiki hal itu sekarang dan telah menyita pengiriman.",
  ui_story_5072_50721602_61_dialog_content = "Dia kehilangan semua uangnya dan mungkin sedang meluapkan amarah saat kita bicara.",
  ui_story_5072_50721602_62_dialog_content = "Begitu. Sepertinya pria itu benar-benar sedang sial sekarang.",
  ui_story_5072_50721602_63_dialog_content = "Apa yang berputar akan kembali berputar. Kamu harus berhati-hati bahkan ketika kamu berada di puncak.",
  ui_story_5072_50721602_64_dialog_content = "Atau Anda tidak akan memiliki tempat untuk pergi selain turun ketika situasi berbalik.",
  ui_story_5072_50721602_65_dialog_content = "Nikmatilah..!",
  ui_story_5072_50721602_66_dialog_content = "Dalam kemalangan orang lain...!",
  ui_story_5072_50721602_67_dialog_content = "Lupakan orang malang itu dan selesaikan ceritamu!",
  ui_story_5072_50721602_68_dialog_content = "Tentu. Melanjutkan dari tempat kita berhenti, pendekar pedang datang ke Twin Pavilions Bay.",
  ui_story_5072_50721602_69_dialog_content = "Dalam tugas dari seorang pengrajin asing untuk membuang pedang terkutuk yang dapat mengendalikan pikiran itu.",
  ui_story_5072_50721602_70_dialog_content = "Pendekar pedang menemukan, bertarung, dan mengurung pedang terkutuk.",
  ui_story_5072_50721602_X70_dialog_content = "Hanya untuk pedang terkutuk itu beresonansi dengan pedang ajaibnya sendiri.",
  ui_story_5072_50721602_71_dialog_content = "Yang hampir menjebak pendekar pedang di bawah mantra itu.",
  ui_story_5072_50721602_72_dialog_content = "Untungnya, pedang sihirnya muncul pada momen krusial dan menunjukkan ceritanya sendiri untuk memecahkan cengkeraman.",
  ui_story_5072_50721602_X72_dialog_content = "Kemudian, pendekar pedang itu menantang pedang terkutuk untuk duel di bawah bulan purnama.",
  ui_story_5072_50721602_X73_dialog_content = "Di bawah sinar bulan purnama, di atas benteng Twin Pavilions Bay, mereka bertempur dalam pertempuran yang seimbang...",
  ui_story_5072_50721602_73_dialog_content = "Ayo, ceritakan siapa yang menang!",
  ui_story_5072_50721602_74_dialog_content = "Kamu pikir kita akan menikmati semua ini jika pedang terkutuk menang?",
  ui_story_5072_50721602_75_dialog_content = "Hmm…",
  ui_story_5072_50721602_76_dialog_content = "Seperti yang mereka katakan...",
  ui_story_5072_50721602_77_dialog_content = "Perlakukan pedang seperti Anda memperlakukan orang dan pedang akan membalas dengan cara yang sama.",
  ui_story_5072_50721602_78_dialog_content = "Dalam mimpi, yang mustahil menjadi mungkin. Duri bisa berbunga, pedang bisa berbicara.",
  ui_story_5072_50721602_79_dialog_content = "Pedang mengungkapkan apa yang ada di pikiranmu, jangan lupa apa yang kamu dengar dalam mimpimu!",
  ui_story_5072_50721602_80_dialog_content = "Semua yang kamu lakukan hanyalah membuat kami tegang. Ayo kita pergi dari sini!",
  ui_story_5072_50721602_81_dialog_content = "Sudah waktunya bagi saya untuk pergi juga.",
  ui_story_5072_50721602_82_dialog_content = "Semoga mimpi indah, semua. Sampai jumpa di lain waktu!",
  ui_story_5072_50721701_1_dialog_content = "Berhenti! Ini adalah kapal pribadi. Tidak ada yang bisa masuk tanpa izin!",
  ui_story_5072_50721701_2_dialog_content = "Baiklah, seorang pelayan sedang menjaganya. Sampai jumpa lain kali.",
  ui_story_5072_50721702_1_dialog_content = "Berhenti! Ini adalah kapal pribadi. Tidak ada yang bisa masuk tanpa izin!",
  ui_story_5072_50721702_2_dialog_content = "Saya memiliki surat perintah dari Lins dan Umbraton Guild. Tempat ini melindungi seorang penjahat dan kita harus mencari di sekitarnya!",
  ui_story_5072_50721702_3_dialog_content = "Surat perintah? Urusan resmi yang sah, saya mengerti! Saya harus pergi dari sini!"
}
return config
